            target += 10 * Math.sin(_prismTime * 0.22);
        }
        _prismHue = _hueLerpAngle(_prismHue, target, 0.055);
        _prismAmp += (levelNow - _prismAmp) * 0.18;
        if (_prismAmp < 0) _prismAmp = 0;
        if (_prismAmp > 1) _prismAmp = 1;
