    // Gemini round-trip; interrupted or queued when the real reply lands.
    // Lines written in warm Indian-English help-desk register.
    var FILLER_PHRASES = [
        // SHORT (~1s)
        'One moment, please.',
        'Just a sec, looking that up.',
        'Checking on that now.',
        'Let me pull that up.',
        'Hold on, fetching it.',
        'Right, looking into it.',
        'Give me a moment, Mihir.',
        'One second, please.',
        'Pulling that up for you.',
        // MEDIUM (~2s)
        'Just a moment, I am checking on that.',
        'Hold on, let me pull that up for you.',
        'Okay, fetching that information right now.',
        'One moment please, I am looking into it.',
        'Bear with me, just pulling the details.',
        'Got it, checking the system now.',
        'Let me see what I can find.',
        'Hang on a second, almost there.',
        'Alright Mihir, looking that up now.',
        'Just checking the records, one moment.',
        // LONG (~3s)
        'Give me a moment, I am pulling that information from the system now.',
        'Bear with me for a second, I am just looking into the details.',
        'One moment please, I am checking that on my end for you.',
        'Hold on Mihir, I am fetching the latest information for you right now.',
        'Let me check on that quickly, should only take a moment.',
        'Just a moment please, I am getting that sorted out for you.',
        'Hang on for a second, I am cross-checking the details right now.',
        'Alright, looking into that for you, should have it shortly.',
        // R5 - VR analyst flavored (MEDIUM)
        'Checking the vulnerability queue now.',
        'Scanning the risk data, one moment.',
        'Let me pull the exposure numbers.',
        'Digging into the security backlog for you.',
        // R7 - witty companion flavor
        'Ooh, good one. Digging in.',
        'On it... pretend I am typing furiously.',
        'Let me snoop around for a second.',
        'Hmm, hold that thought... almost there.',
        'Interesting... give me a beat.',
        'One sec, working my magic.'
    ];
    var fillerCache = [];   // [{url, text}]
    var lastFillerPlayedAt = 0;
    var currentFillerAudio = null;
    // R3.7 - filler chain state. While _fillerChainActive is true, fillers
    // auto-loop until the server replies. _pendingReply queues the real
    // response if it arrives in the second half of a filler. _currentFillerEst
    // is the estimated total ms of the currently-playing filler audio.
    var _fillerChainActive = false;
    var _pendingReply       = null;   // {text, done, queuedAt}
    var _currentFillerStart = 0;
    var _currentFillerEst   = 0;

    function _edgeBlob(text, voice, cb) {
        _edgeWssUrl(function (wssUrl, requestId) {
        try {
            var ws = new WebSocket(wssUrl);
            ws.binaryType = 'arraybuffer';
            var chunks = [];
            var done = false;
            var watchdog = $timeout(function () {
                if (!done) { done = true; try { ws.close(); } catch (e) {} cb(null); }
            }, 5000);
            ws.onopen = function () {
                var cfg = '{"context":{"synthesis":{"audio":{"metadataoptions":{"sentenceBoundaryEnabled":"false","wordBoundaryEnabled":"false"},"outputFormat":"' + EDGE_AUDIO_FORMAT + '"}}}}';
                ws.send('X-Timestamp:' + new Date().toISOString() + '\r\nContent-Type:application/json; charset=utf-8\r\nPath:speech.config\r\n\r\n' + cfg);
                var safe = String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
                var ssml = '<speak version=\'1.0\' xml:lang=\'en-US\'><voice name=\'' + (voice || c.edgeVoice) + '\'>' +
                           '<prosody rate=\'+6%\' pitch=\'+0Hz\'>' + safe + '</prosody></voice></speak>';
                ws.send('X-RequestId:' + requestId + '\r\nContent-Type:application/ssml+xml\r\nX-Timestamp:' + new Date().toISOString() + '\r\nPath:ssml\r\n\r\n' + ssml);
            };
            ws.onmessage = function (ev) {
                if (typeof ev.data === 'string') {
                    if (ev.data.indexOf('Path:turn.end') >= 0) {
                        try { ws.close(); } catch (e) {}
                        if (done) return;
                        done = true;
                        $timeout.cancel(watchdog);
                        if (!chunks.length) { cb(null); return; }
                        cb(new Blob(chunks, { type: 'audio/mp3' }));
                    }
                } else {
                    var data = new Uint8Array(ev.data);
                    if (data.length < 2) return;
                    var headerLen = (data[0] << 8) | data[1];
                    if (data.length > 2 + headerLen) chunks.push(data.slice(2 + headerLen));
                }
            };
            ws.onerror = function () { if (!done) { done = true; $timeout.cancel(watchdog); cb(null); } };
            ws.onclose = function () { if (!done) { done = true; $timeout.cancel(watchdog); cb(null); } };
        } catch (e) { cb(null); }
        });   // _edgeWssUrl
    }

    function preloadFillers() {
        if (typeof WebSocket === 'undefined') return;
        // R4.3 - respect the persisted circuit breaker. If Edge has already
        // failed >=REMOTE_FAIL_LIMIT times across previous sessions, don't
        // spam 27 more failed WSS connections at boot - they all fail
        // identically. The filler chain (R4.1) will use live browser TTS
        // instead.
        if (_edgeCircuitOpen()) {
            logEvent('tts', 'skipping filler preload - edge circuit open (' + _edgeFails + ' prior fails); chain will use live browser TTS');
            return;
        }
        logEvent('tts', 'pre-loading thinking-cue fillers...');
        var pending = FILLER_PHRASES.length;
        FILLER_PHRASES.forEach(function (phrase) {
            _edgeBlob(phrase, c.edgeVoice, function (blob) {
                if (blob) {
                    var url = URL.createObjectURL(blob);
                    fillerCache.push({ url: url, text: phrase });
                }
                if (--pending === 0) {
                    logEvent('tts', 'filler cache ready (' + fillerCache.length + '/' + FILLER_PHRASES.length + ')');
                }
            });
        });
    }

    function playThinkingFiller() {
        // R3.7 - one-shot fallback used only by setState transitions.
        // The main flow uses startFillerChain / stopFillerChain.
        if (!fillerCache.length || _fillerChainActive) return;
        if (Date.now() - lastFillerPlayedAt < 4000) return;
        _playOneFiller(null);
    }

    /* ============================================================
     *  R3.7 - FILLER CHAIN
     *
     *  startFillerChain():  begin auto-looping fillers while waiting
     *                       for the server response.
     *  deliverServerReply(text, done):
     *      Real reply arrived. If a filler is currently playing:
     *        - <50% spoken -> interrupt with "Oh wait, ..." + reply
     *        - >=50% spoken -> queue reply for after current filler ends
     *      If no filler playing -> speak the reply directly.
     *  stopFillerChain():   abort the chain (used on errors).
     * ============================================================ */
    function _estimateFillerMs(text) {
        // ~330 ms per word at 1.15x rate, min 1.2s, max 5s
        var words = (text || '').split(/\s+/).length;
        return Math.max(1200, Math.min(5000, words * 330));
    }
    // R4.1 - track the active filler utterance so we can cancel it on
    // interrupt or stop. currentFillerAudio handles the Edge blob path;
    // currentFillerUtter handles the browser-TTS runtime path.
    var currentFillerUtter = null;
    function _playFillerLive(text, onDone) {
        // Synthesize a filler at runtime via SpeechSynthesis. Used when
        // the Edge pre-cache is empty (Edge WSS blocked) so fillers
        // still play instead of silence.
        if (typeof speechSynthesis === 'undefined' || !c.hasTTS) {
            if (onDone) onDone();
            return null;
        }
        try {
            // Don't cancel the existing utterance queue here - that would
            // also stop the real reply if it's already speaking. Filler
            // chain interrupt path calls speechSynthesis.cancel separately.
            var u = new SpeechSynthesisUtterance(text);
            u.rate   = 1.0;
            u.pitch  = 0.98;
            u.volume = 0.9;
            u.lang   = 'en-IN';
            var v = chooseVoice();
            if (v) { u.voice = v; }
            var fired = false;
            var fire = function () { if (fired) return; fired = true; if (onDone) onDone(); };
            u.onend = fire;
            u.onerror = fire;
            speechSynthesis.speak(u);
            return u;
        } catch (e) {
            logEvent('warn', 'filler live failed: ' + e.message);
            if (onDone) onDone();
            return null;
        }
    }
    function _playOneFiller(onEndedExtra) {
        // Clear any in-flight filler before starting a new one
        if (currentFillerAudio) {
            try { currentFillerAudio.pause(); } catch (e) {}
            currentFillerAudio = null;
        }
        if (currentFillerUtter && typeof speechSynthesis !== 'undefined') {
            try { speechSynthesis.cancel(); } catch (e) {}
            currentFillerUtter = null;
        }
        // R4.1 - Path A: Edge cache populated -> play pre-rendered blob (best quality)
        if (fillerCache.length) {
            var f = fillerCache[Math.floor(Math.random() * fillerCache.length)];
            var a = new Audio(f.url);
            a.volume = 0.85;
            a.playbackRate = 1.0;
            currentFillerAudio = a;
            _fillerEchoText = f.text;   // R6 - echo-scorer must know this line
            _currentFillerStart = Date.now();
            _currentFillerEst = _estimateFillerMs(f.text);
            lastFillerPlayedAt = Date.now();
            logEvent('tts', 'filler[blob]: "' + f.text + '" (~' + _currentFillerEst + 'ms)');
            a.onended = function () {
                if (currentFillerAudio === a) currentFillerAudio = null;
                if (onEndedExtra) onEndedExtra();
            };
            a.onerror = function () {
                if (currentFillerAudio === a) currentFillerAudio = null;
                if (onEndedExtra) onEndedExtra();
            };
            a.play().catch(function () {
                if (currentFillerAudio === a) currentFillerAudio = null;
                if (onEndedExtra) onEndedExtra();
            });
            return;
        }
        // R4.1 - Path B: no cache (Edge blocked) -> synthesize live via
        // browser TTS. Slightly less natural than Aria/Raveena but always
        // works on networks where Edge WSS and StreamElements are blocked.
        var phrase = FILLER_PHRASES[Math.floor(Math.random() * FILLER_PHRASES.length)];
        _fillerEchoText = phrase;   // R6 - echo-scorer must know this line
        _currentFillerStart = Date.now();
        _currentFillerEst = _estimateFillerMs(phrase);
        lastFillerPlayedAt = Date.now();
        logEvent('tts', 'filler[live]: "' + phrase + '" (~' + _currentFillerEst + 'ms)');
        currentFillerUtter = _playFillerLive(phrase, function () {
            currentFillerUtter = null;
            if (onEndedExtra) onEndedExtra();
        });
        if (!currentFillerUtter) {
            // synthesis unavailable - skip ahead so the chain keeps moving
            $timeout(function () { if (onEndedExtra) onEndedExtra(); }, 50);
        }
    }
    function startFillerChain() {
        if (_fillerChainActive) return;
        // R4.1 - removed the "no cache -> skip" guard. We can now synthesize
        // live, so the chain always starts. fillerCache acts as an optimisation
        // when Edge WSS works; runtime browser TTS is the fallback.
        _fillerChainActive = true;
        _pendingReply = null;
        logEvent('tts', 'filler chain start (cache=' + fillerCache.length + ')');
        var advance = function () {
            // If a real reply was queued, deliver it now.
            if (_pendingReply) {
                var p = _pendingReply;
                _pendingReply = null;
                _fillerChainActive = false;
                logEvent('tts', 'filler chain -> queued reply');
                speak(p.text, p.done);
                return;
            }
            if (!_fillerChainActive) return;   // stopped externally
            // Short gap, then next filler. The gap is small enough that the
            // pause feels like a breath, not a stop.
            $timeout(function () {
                if (!_fillerChainActive) return;
                _playOneFiller(advance);
            }, 250);
        };
        _playOneFiller(advance);
    }
    function stopFillerChain() {
        if (!_fillerChainActive && !currentFillerAudio && !currentFillerUtter) return;
        _fillerChainActive = false;
        _pendingReply = null;
        // R4.1 - also cancel any live browser-TTS filler utterance
        if (currentFillerUtter && typeof speechSynthesis !== 'undefined') {
            try { speechSynthesis.cancel(); } catch (e) {}
            currentFillerUtter = null;
        }
        if (currentFillerAudio) {
            try { currentFillerAudio.pause(); } catch (e) {}
            currentFillerAudio = null;
        }
        logEvent('tts', 'filler chain stop');
    }
    function deliverServerReply(text, done) {
        // Server reply arrived. Decide: interrupt, queue, or just speak.
        if (!_fillerChainActive && !currentFillerAudio && !currentFillerUtter) {
            // No filler running - normal speak
            speak(text, done);
            return;
        }
        // R4.1 - support both blob fillers (currentFillerAudio) and live
        // browser-TTS fillers (currentFillerUtter). Compute ratio against
        // whichever is active.
        var elapsed = Date.now() - _currentFillerStart;
        var realMs = _currentFillerEst;
        if (currentFillerAudio && currentFillerAudio.duration && isFinite(currentFillerAudio.duration)) {
            realMs = currentFillerAudio.duration * 1000 / (currentFillerAudio.playbackRate || 1);
        }
        var ratio = realMs > 0 ? elapsed / realMs : 1;
        if (currentFillerAudio || currentFillerUtter) {
            if (ratio < 0.5) {
                logEvent('tts', 'reply interrupts filler at ' + Math.round(ratio*100) + '% -> "Oh wait..."');
                if (currentFillerAudio) { try { currentFillerAudio.pause(); } catch (e) {} currentFillerAudio = null; }
                if (currentFillerUtter && typeof speechSynthesis !== 'undefined') { try { speechSynthesis.cancel(); } catch (e) {} currentFillerUtter = null; }
                _fillerChainActive = false;
                _pendingReply = null;
                var prefixed = 'Oh wait, I have it. ' + text;
                speak(prefixed, done);
            } else {
                logEvent('tts', 'reply queued behind filler at ' + Math.round(ratio*100) + '%');
                _pendingReply = { text: text, done: done, queuedAt: Date.now() };
            }
        } else {
            // Chain active but between fillers - just speak immediately
            _fillerChainActive = false;
            speak(text, done);
        }
    }

    function speakStreamElements(text, done) {
        // R3.5.2 - skip remote entirely if circuit is open
        if (_streamFails >= REMOTE_FAIL_LIMIT) {
            return speakBrowser(text, done);
        }
        // Stop any currently playing remote audio
        if (currentAudio) {
            try { currentAudio.pause(); currentAudio.src = ''; } catch (e) {}
            currentAudio = null;
        }
        // Also stop browser TTS so we never overlap
        if (TTS && (TTS.speaking || TTS.pending)) {
            try { TTS.cancel(); } catch (e) {}
        }
        var voice = c.remoteVoice || REMOTE_TTS_VOICE;
        var url = 'https://api.streamelements.com/kappa/v2/speech?voice=' +
                  encodeURIComponent(voice) + '&text=' + encodeURIComponent(text);
        logEvent('tts', 'remote: ' + voice + ' (' + text.length + ' chars)');

        // R1.1 - cap to 15s. If TTS hangs, mic stays blocked for at most 15s
        // instead of a full minute. onended/onerror normally fires <10s.
        _markSpeaking(text);   // R6 - hot mic: echo-scored, not deafened

        var audio = new Audio();
        audio.src = url;
        audio.volume = 1.0;
        audio.playbackRate = 1.05;   // R7 - StreamElements voices are slow; mild lift only
        currentAudio = audio;

        // Single fallback guard - whichever signal fires first wins
        var resolved = false;
        var fallback = function (reason) {
            if (resolved) return;
            resolved = true;
            $timeout.cancel(watchdog);
            try { audio.pause(); audio.src = ''; } catch (e) {}
            detachOutputAnalyser(audio);
            if (currentAudio === audio) currentAudio = null;
            _streamFallback(text, done, reason);   // R3.5.2 - bumps circuit + logs
        };
        var finish = function () {
            if (resolved) return;
            resolved = true;
            $timeout.cancel(watchdog);
            detachOutputAnalyser(audio);
            _clearSpeaking();   // R6
            if (currentAudio === audio) currentAudio = null;
            if (done) done();
        };

        var watchdog = $timeout(function () { fallback('no playback in 4s'); }, 4000);

        // R2.9.1 - state must flip to speaking BEFORE the analyser ticks so the
        // recompute picks up VOICE_RING_BASE_SPEAKING + spike. Then attach.
        setState('speaking');
        attachOutputAnalyser(audio);
        audio.onplaying = function () {
            if (resolved) return;
            $timeout.cancel(watchdog);
            _streamFails = 0;
            _ssSet('netra_streamFails', 0);   // R4.2 - clear persisted breaker on recovery
            logEvent('tts', 'remote playing');
        };
        audio.onended = function () { if (!resolved) { logEvent('tts', 'remote ended'); finish(); } };
        audio.onerror = function () { fallback('audio.onerror'); };

        var playPromise = audio.play();
        if (playPromise && playPromise.then) {
            playPromise.then(
                function () { /* onplaying will fire */ },
                function (err) { fallback('play() rejected: ' + (err && err.message || err)); }
            );
        }
    }

    function speakBrowser(text, done) {
        // Stop any remote audio first - critical to avoid overlap when called as fallback
        if (currentAudio) {
            try { currentAudio.pause(); currentAudio.src = ''; } catch (e) {}
            currentAudio = null;
        }
        if (!c.hasTTS) {
            logEvent('err', 'no browser TTS available');
            if (done) done();
            return;
        }
        if (!text) { if (done) done(); return; }

        // R1.1 - 15s cap (was 60s). Watchdog also clears stale guards.
        _markSpeaking(text);   // R6 - hot mic: echo-scored, not deafened

        if (TTS.speaking || TTS.pending) {
            TTS.cancel();
        }

        // R3.8 - Web Speech API has no SSML support, so strip the markdown
        // emphasis + ellipsis markers we kept around for the SSML path.
        // SpeechSynthesisUtterance also has no break-time tag, so we just
        // rely on natural punctuation pauses.
        // R4.5 - hard cap on plain to Chrome's ~32KB utterance limit,
        // with a safe margin. Long text silently stalls otherwise.
        var plain = String(text || '')
            .replace(/\*\*([^*]+)\*\*/g, '$1')
            .replace(/\*/g, '')
            .replace(/\.{3,}/g, ',');   // ellipsis -> short pause via comma
        if (plain.length > 28000) plain = plain.substring(0, 28000) + '...';
        var u = new SpeechSynthesisUtterance(plain);
        u.rate  = c.speechRate || 1.06;   // R13 - follow the pace slider here too
        u.pitch = 1.05;
        u.volume = 1.0;
        var v = chooseVoice();
        if (v) {
            u.voice = v;
            u.lang  = v.lang || 'en-IN';
            logEvent('tts', 'browser: ' + v.name + ' / ' + (v.lang || 'en-IN') + ' (' + text.length + ' chars)');
        } else {
            // R13 - even with no matching voice object, follow the locale
            // of the picked voice instead of hardcoding en-IN
            u.lang = (String(c.edgeVoice || '').match(/^[a-z]{2}-[A-Z]{2}/) || ['en-IN'])[0];
            logEvent('tts', 'browser DEFAULT voice for ' + u.lang + ' (' + text.length + ' chars)');
        }

        var startedAt = Date.now();
        var startWatchdog = $timeout(function () {
            if (Date.now() - startedAt > 1800 && !TTS.speaking) {
                logEvent('warn', 'TTS never fired onstart in 1.8s - voice may be silent or autoplay blocked');
            }
        }, 2000);

        u.onstart = function () {
            $timeout.cancel(startWatchdog);
            setState('speaking');
            logEvent('tts', 'onstart');
        };
        u.onend = function () {
            $timeout.cancel(startWatchdog);
            _clearSpeaking();   // R6
            logEvent('tts', 'onend');
            if (done) done();
        };
        u.onerror = function (ev) {
            $timeout.cancel(startWatchdog);
            _clearSpeaking();   // R6
            logEvent('err', 'TTS error: ' + (ev && ev.error));
            if (done) done();
        };

        try {
            // Small delay helps Chrome after cancel()
            $timeout(function () { TTS.speak(u); }, 60);
        } catch (e) {
            logEvent('err', 'TTS.speak threw: ' + e);
            if (done) done();
        }
    }

    function chooseVoice() {
        if (!c.hasTTS) return null;
        var voices = TTS.getVoices() || [];
        if (!voices.length) return null;
        if (forcedVoiceName) {
            var fv = voices.find(function (vv) { return vv.name === forcedVoiceName; });
            if (fv) return fv;
        }
        // R13 FIX - the browser fallback now honors the picked voice too:
        // match the same speaker name first (Edge exposes "Microsoft Ava
        // Online (Natural)..." locally), then the same locale, and only
        // then the generic quality picker. Before this, falling back to
        // browser TTS silently ignored the user's choice.
        try {
            var mV = String(c.edgeVoice || '').match(/^([a-z]{2}-[A-Z]{2})-([A-Za-z]+?)(Multilingual)?Neural$/);
            if (mV) {
                var wantLoc = mV[1], wantName = mV[2];
                var byName = voices.find(function (vv) { return vv.name.indexOf(wantName) >= 0; });
                if (byName) return byName;
                var sameLoc = function (vv) { return String(vv.lang || '').replace('_', '-').indexOf(wantLoc) === 0; };
                var byLoc = voices.find(function (vv) { return sameLoc(vv) && /Natural|Neural|Online|Google/i.test(vv.name); }) ||
                            voices.find(sameLoc);
                if (byLoc) return byLoc;
            }
        } catch (eCV) {}
        return pickFemaleVoice();
    }

    // R8 - browser TTS is the ALWAYS-AVAILABLE fallback, so its quality
    // matters. Modern OSes ship genuinely good neural voices (Edge/Chrome
    // "Natural", macOS "Samantha"/"Ava", Google voices). The old picker
    // hunted only for en-IN names and dropped to a robotic default when it
    // found none - which is exactly what happens on a US/EU Windows box.
    // New order: best NEURAL English voice first (any region), a good
    // female name second, then any English, then anything. Quality beats
    // accent for the fallback.
    function pickFemaleVoice() {
        if (!c.hasTTS) return null;
        var voices = TTS.getVoices() || [];
        if (!voices.length) return null;

        var isEng = function (v) { return /^en([-_]|$)/i.test(v.lang || ''); };
        var find = function (pred) { for (var i = 0; i < voices.length; i++) if (pred(voices[i])) return voices[i]; return null; };

        // Tier 1: top-shelf neural voices by exact name, best first.
        var premium = [
            'Ava', 'Aria', 'Emma', 'Jenny', 'Michelle', 'Sonia', 'Libby',
            'Google US English', 'Google UK English Female',
            'Samantha', 'Karen', 'Moira', 'Tessa', 'Neerja', 'Heera'
        ];
        var pick = null;
        for (var i = 0; i < premium.length && !pick; i++) {
            (function (nm) {
                pick = find(function (v) { return isEng(v) && v.name.indexOf(nm) >= 0 && /Natural|Neural|Online|Google/i.test(v.name); })
                    || find(function (v) { return isEng(v) && v.name.indexOf(nm) >= 0; });
            })(premium[i]);
        }
        // Tier 2: ANY English voice tagged Natural/Neural/Online (these are
        // the modern high-quality engines regardless of the speaker name).
        if (!pick) pick = find(function (v) { return isEng(v) && /Natural|Neural|Online/i.test(v.name); });
        // Tier 3: prefer a non-"default"/non-eSpeak English voice.
        if (!pick) pick = find(function (v) { return isEng(v) && !/espeak|default/i.test(v.name); });
        // Tier 4: any English at all, then whatever exists.
        if (!pick) pick = find(isEng) || voices[0];

        if (pick) c.voiceName = pick.name + ' (' + pick.lang + ')';
        return pick;
    }

    function populateVoices() {
        if (!c.hasTTS) return;
        var vs = TTS.getVoices() || [];
        c.voices = vs.map(function (v) { return { name: v.name, lang: v.lang }; });
        if (vs.length && c.voiceName === '(picking...)') pickFemaleVoice();
        $scope.$applyAsync();
    }

    /* ============================================================
     *  AUDIO CUES
     * ============================================================ */
    function unlockAudio() {
        if (audioCtx) return;
        try {
            var Ctor = $window.AudioContext || $window.webkitAudioContext;
            audioCtx = new Ctor();
        } catch (e) {}
    }

    function cue(kind) {
        if (!audioCtx) return;
        if (audioCtx.state === 'suspended') {
            try { audioCtx.resume(); } catch (e) {}
        }
        switch (kind) {
            case 'wake':   tone([660, 880], 0.06); break;
            case 'think':  tone([440],      0.04); break;
            case 'error':  tone([440, 220], 0.10); break;
            case 'pause':  tone([330],      0.12); break;
            case 'resume': tone([440, 660], 0.08); break;
        }
    }

    function tone(freqs, dur) {
        try {
            var now = audioCtx.currentTime;
            freqs.forEach(function (f, idx) {
                var osc = audioCtx.createOscillator();
                var g   = audioCtx.createGain();
                osc.type = 'sine';
                osc.frequency.value = f;
                osc.connect(g);
                g.connect(audioCtx.destination);
                var start = now + idx * dur;
                g.gain.setValueAtTime(0.0001, start);
                g.gain.exponentialRampToValueAtTime(0.12, start + 0.01);
                g.gain.exponentialRampToValueAtTime(0.0001, start + dur);
                osc.start(start);
                osc.stop(start + dur + 0.02);
            });
        } catch (e) {}
    }

    /* ============================================================
     *  HOTKEYS
     * ============================================================ */
    function bindHotkeys() {
        $window.addEventListener('keydown', function (e) {
            if (e.altKey && (e.key === 'n' || e.key === 'N')) {
                e.preventDefault();
                c.tap();
                $scope.$applyAsync();
            }
            if (e.altKey && e.shiftKey && (e.key === 'r' || e.key === 'R')) {
                // R2.7 - Alt+Shift+R = NUCLEAR reset (history, mic, rec, AudioContext)
                e.preventDefault();
                logEvent('warn', 'Alt+Shift+R: nuclear reset of everything');
                _memForget('nuclear reset');
                recRestartCount = 0;
                ignoreFinalsUntil = Date.now();
                try { if (contRec) contRec.stop(); } catch (er) {}
                try { stopMicLevelMeter(); } catch (e2) {}
                $timeout(function () {
                    startContinuous();
                    startMicLevelMeter();
                }, 300);
                $scope.$applyAsync();
                return;
            }
            if (e.altKey && (e.key === 'r' || e.key === 'R')) {
                // R1.1 - Alt+R = force restart recognition (escape hatch)
                e.preventDefault();
                logEvent('dev', 'Alt+R: force restart recognition');
                recRestartCount = 0;
                ignoreFinalsUntil = Date.now();
                try { if (contRec) contRec.stop(); } catch (er) {}
                $timeout(startContinuous, 200);
                $scope.$applyAsync();
            }
            if (e.altKey && (e.key === 'd' || e.key === 'D')) {
                e.preventDefault();
                c.toggleDev();
                $scope.$applyAsync();
            }
            if (e.key === 'Escape') {
                // R6 - Escape now silences EVERYTHING (remote audio, browser
                // TTS, filler chain, pipeline queue) via the universal stopper.
                // The old handler only cancelled browser TTS, so Escape did
                // nothing during Edge/Gemini/Stream playback.
                stopSpeaking('Escape key');
                $scope.$applyAsync();
            }
        });
    }

    /* ============================================================
     *  NOTIFICATION POLLING
     * ============================================================ */
    function startNotificationPolling() {
        var POLL_MS_ACTIVE  = 9000;
        var POLL_MS_DORMANT = 30000;   // R4.7 - back off when paused/dormant
        var tick = function () {
            // R4.7 - PERF: keep the poll payload minimal. handleHeard leaves the
            // full conversation history, the last response, and any screenshot
            // on c.data; without clearing them, every 9s poll re-POSTed all of
            // that upstream. Null them so the poll round-trip stays tiny. The
            // next chat re-sets history/message before it sends.
            c.data.action    = 'poll';
            c.data.message   = null;
            c.data.history   = null;
            c.data.image_b64 = null;
            c.data.response  = null;
            c.server.update().then(
                function () {
                    var list = c.data.notifications || [];
                    if (list.length) logEvent('poll', list.length + ' new');
                    list.forEach(function (n) {
                        if (seenIds[n.id]) return;
                        seenIds[n.id] = true;
                        // R4.5 - cap seenIds to last 500 keys so long-lived
                        // PWA sessions don't accumulate thousands of sys_ids.
                        var _seenKeys = Object.keys(seenIds);
                        if (_seenKeys.length > 500) {
                            for (var _si = 0; _si < _seenKeys.length - 500; _si++) {
                                delete seenIds[_seenKeys[_si]];
                            }
                        }
                        if (c.state === 'listening' || c.state === 'speaking' || c.state === 'awaiting' || c.state === 'thinking') return;
                        if (!c.alert) return;  // don't disturb when dormant
                        // R8.2 - skip a scanner-promoted reminder that the local
                        // timer already announced to the minute.
                        if (n.kind === 'reminder' && _reminderAlreadySpoken(n.message)) {
                            logEvent('poll', 'reminder already spoken locally - skipped');
                            return;
                        }
                        // R6 - interjection etiquette: if we are mid-conversation
                        // (user spoke within the last 45s), Netra excuses herself
                        // before delivering, like a colleague leaning in.
                        var msg = n.message;
                        var recentlyTalking = c.conversationOpen && (Date.now() - (recLastActivityAt || 0) < 45000);
                        if (recentlyTalking) {
                            var lead = ['Sorry to cut in - ', 'Oh - one quick thing - ', 'Pardon the interruption - '];
                            msg = lead[Math.floor(Math.random() * lead.length)] + msg;
                        }
                        c.spoken = msg;
                        $scope.$applyAsync();
                        speak(msg);
                    });
                },
                function () { /* silent */ }
            ).finally(function () {
                // R4.7 - poll slower while paused or dormant: the server has
                // nothing to deliver then, so a 9s cadence was wasted chatter.
                var dormant = (c.data && c.data.paused) || !c.alert;
                pollTimer = $timeout(tick, dormant ? POLL_MS_DORMANT : POLL_MS_ACTIVE);
            });
        };
        pollTimer = $timeout(tick, 3000);
    }

    /* ============================================================
     *  DEV PANEL ACTIONS
     * ============================================================ */
    c.toggleDev = function () {
        c.devOn = !c.devOn;
        logEvent('dev', 'panel ' + (c.devOn ? 'shown' : 'hidden'));
    };

    c.devKey = function (e) {
        if (e && e.keyCode === 13) {
            e.preventDefault();
            c.devSendText();
        }
    };

    c.devSendText = function () {
        var t = (c.devText || '').trim();
        if (!t) return;
        c.devText = '';
        logEvent('dev', 'manual send: "' + t + '"');
        unlockAudio();
        // Run through the same pipeline as a voice command
        processCommand(t, 1.0);
    };

    c.devListenNow = function () {
        unlockAudio();
        logEvent('dev', 'manual arm - next utterance is the command');
        commandMode = true;
        setState('awaiting');
        cue('wake');
        if (commandTimer) $timeout.cancel(commandTimer);
        commandTimer = $timeout(function () {
            if (commandMode) {
                commandMode = false;
                logEvent('wake', 'manual arm timed out');
                setState(c.alert ? 'idle' : 'dormant');
            }
        }, WAKE_TIMEOUT_MS);
    };

    c.devTestTTS = function () {
        unlockAudio();
        logEvent('dev', 'TEST TTS using ' + c.voiceName);
        speak('This is a test of the voice. Kindly let me know if you can hear me clearly. I am Netra, speaking in Indian English.');
    };

    c.devGreet = function () {
        unlockAudio();
        var name = (c.data && c.data.user_name) ? c.data.user_name : 'there';
        speak('Hello ' + name + '. I am Netra, ready to help.');
    };

    c.devReplayLast = function () {
        if (!lastReply) { logEvent('dev', 'no last reply to replay'); return; }
        speak(lastReply);
    };

    c.devToggleSleep = function () {
        c.tap();
    };

    c.devRestartRec = function () {
        logEvent('dev', 'restarting recognition session');
        try { if (contRec) contRec.stop(); } catch (e) {}
        // onend will restart automatically
    };

    c.devClearLog = function () {
        c.events = [];
    };

    // R2.7 - exposes Alt+Shift+R as a button click for sighted helpers
    c.devNuclearReset = function () {
        logEvent('warn', 'Reset all clicked - nuclear reset');
        _memForget('nuclear reset');
        recRestartCount = 0;
        ignoreFinalsUntil = Date.now();
        try { if (contRec) contRec.stop(); } catch (e) {}
        try { stopMicLevelMeter(); } catch (e) {}
        $timeout(function () {
            startContinuous();
            startMicLevelMeter();
        }, 300);
    };

    c.devPickVoice = function () {
        forcedVoiceName = c.voicePick || '';
        if (forcedVoiceName) {
            c.voiceName = forcedVoiceName + ' (forced)';
            logEvent('dev', 'voice forced to ' + forcedVoiceName);
        } else {
            logEvent('dev', 'voice auto - re-picking');
            pickFemaleVoice();
        }
    };

    c.devPingServer = function () {
        logEvent('dev', 'pinging server...');
        c.data.action = 'debug';
        c.server.update().then(
            function () {
                var d = c.data.debug || {};
                logEvent('srv', 'ping ok: model=' + d.model + ' key=' + d.api_key_status +
                                ' tools=' + (d.tool_count || '?'));
                if (d.tools && d.tools.length) {
                    logEvent('srv', 'available tools: ' + d.tools.join(', '));
                }
            },
            function (err) {
                logEvent('err', 'ping failed: ' + err);
            }
        );
    };

    // R7 - voice picker + pace slider (persisted; used by the Edge SSML path)
    c.devSetEdgeVoice = function () {
        try { localStorage.setItem('netra_edgeVoice', c.edgeVoice); } catch (e) {}
        // R13 FIX - picking a voice is a clear "I want to hear THIS" signal:
        // reopen the edge/stream circuits so the pick actually plays instead
        // of being silently swallowed by a breaker from some old failure.
        // (This was THE "voice never changes" bug - edge had tripped, every
        // reply fell back to remote/browser and ignored the picker.)
        _edgeFails = 0; _streamFails = 0;
        _ssSet('netra_edgeFails', 0); _ssSet('netra_streamFails', 0);
        // R13 FIX - the pre-baked filler/backchannel audio was rendered in
        // the OLD voice at boot and never refreshed, so "Mm-hmm" and the
        // thinking cues kept the previous voice forever. Rebuild them.
        try {
            fillerCache.forEach(function (f) { try { URL.revokeObjectURL(f.url); } catch (e1) {} });
            backchannelCache.forEach(function (b) { try { URL.revokeObjectURL(b.url); } catch (e2) {} });
            fillerCache.length = 0;
            backchannelCache.length = 0;
            $timeout(preloadFillers, 400);
            $timeout(preloadBackchannels, 900);
        } catch (eVC) {}
        logEvent('dev', 'voice -> ' + c.edgeVoice + ' (TTS circuits reset, filler cache rebuilding in the new voice)');
    };
    c.devSetRate = function () {
        var r = parseFloat(c.speechRate);
        if (!(r >= 0.85 && r <= 1.3)) { c.speechRate = 1.06; r = 1.06; }
        try { localStorage.setItem('netra_speechRate', String(r)); } catch (e) {}
    };
    c.devPreviewVoice = function () {
        var first = String(c.data && c.data.user_name || '').split(' ')[0] || 'there';
        var nice = String(c.edgeVoice).replace(/^[a-z]{2}-[A-Z]{2}-/, '').replace(/Neural$/, '');
        speak('Hey ' + first + '... this is my ' + nice + ' voice at ' +
              (Math.round((c.speechRate - 1) * 100) || 'natural') + ' percent pace. **Pretty smooth**, right?');
    };
    c.devClearConvo = function () { c.convo = []; };

    c.devToggleTTS = function () {
        // R2.8 - cycle: edge -> gemini -> stream -> browser -> edge
        var seq = ['edge', 'gemini', 'stream', 'browser'];
        var idx = seq.indexOf(c.ttsEngine || 'edge');
        c.ttsEngine = seq[(idx + 1) % seq.length];
        c.useRemoteTTS = (c.ttsEngine !== 'browser');
        logEvent('dev', 'TTS engine -> ' + c.ttsEngine +
                 (c.ttsEngine === 'edge'   ? ' (' + c.edgeVoice + ', Microsoft Neural, free)' :
                  c.ttsEngine === 'gemini' ? ' (' + c.geminiVoice + ', Gemini native, ~1 Gemini quota / turn)' :
                  c.ttsEngine === 'stream' ? ' (StreamElements ' + c.remoteVoice + ')' :
                                             ' (browser ' + c.voiceName + ')'));
    };

    c.devCycleRemoteVoice = function () {
        // R2.8 - cycle voices for the active engine
        if (c.ttsEngine === 'edge') {
            var ei = EDGE_VOICES.indexOf(c.edgeVoice);
            c.edgeVoice = EDGE_VOICES[(ei + 1) % EDGE_VOICES.length];
            logEvent('dev', 'Edge voice -> ' + c.edgeVoice);
            return;
        }
        if (c.ttsEngine === 'gemini') {
            var gi = GEMINI_VOICES.indexOf(c.geminiVoice);
            c.geminiVoice = GEMINI_VOICES[(gi + 1) % GEMINI_VOICES.length];
            logEvent('dev', 'Gemini voice -> ' + c.geminiVoice);
            return;
        }
        var voices = ['Raveena','Aditi','Joanna','Salli','Kimberly','Amy','Emma','Brian','Russell','Nicole','Joey','Matthew'];
        var idx = voices.indexOf(c.remoteVoice);
        c.remoteVoice = voices[(idx + 1) % voices.length];
        logEvent('dev', 'remote voice -> ' + c.remoteVoice);
    };

    c.devCloseConversation = function () {
        closeConversation();
        logEvent('dev', 'conversation manually closed');
    };

    c.devDiagnose = function () {
        logEvent('dev', '=== diagnostics ===');
        logEvent('dev', 'SR=' + c.hasSR + ' TTS=' + c.hasTTS + ' Grammars=' + !!SGL);
        logEvent('dev', 'rec running=' + c.recRunning + ' state=' + c.state + ' alert=' + c.alert + ' conv=' + c.conversationOpen);
        logEvent('dev', 'mic permission=' + c.permission);
        logEvent('dev', 'voice=' + (c.useRemoteTTS ? 'remote ' + c.remoteVoice : c.voiceName));
        var enIn = c.voices.filter(function(v){ return /en[-_]IN/i.test(v.lang); });
        logEvent('dev', 'en-IN voices: ' + (enIn.length ? enIn.map(function(v){return v.name;}).join(', ') : 'NONE'));
        logEvent('dev', 'total browser voices: ' + c.voices.length);
        var v = (c.data && c.data.vocab) || {};
        logEvent('dev', 'mined vocab: ' + (v.groups||[]).length + ' groups, ' +
                                          (v.apps||[]).length + ' apps, ' +
                                          (v.categories||[]).length + ' categories, ' +
                                          (v.kb_titles||[]).length + ' KB titles, ' +
                                          (v.catalog_items||[]).length + ' catalog items');
        if (v.built_at) logEvent('dev', 'vocab built at: ' + v.built_at);
    };

    /* ============================================================
     *  STATE
     * ============================================================ */
    // R8 - friendly status line for the Live stage
    var LIVE_STATUS = {
        idle:     'Listening',
        awaiting: 'Listening',
        thinking: 'Thinking…',
        speaking: 'Speaking — just talk to interrupt',
        dormant:  'Muted — tap the blob to wake me',
        error:    'Hmm, hit a snag — say that again?',
        boot:     'Waking up…'
    };
    function setState(s) {
        var prev = c.state;
        c.state = s;
        window.__netraState = s;   // R10 - 3D stage reads this per frame
        c.stateLabel = STATE_LABEL[s] || s;
        c.liveStatus = LIVE_STATUS[s] || 'Listening';
        $scope.$applyAsync();
        // R3.7 - filler chain is now started explicitly from handleHeard()
        // when the server call is dispatched. setState no longer triggers
        // a one-shot filler so we don't double-play.
    }
};

sp_widget.css:
/* ============================================================
 *  Netra Mic widget - styles (R9 "Prism")
 *
 *  the eye/orb is the whole identity - calm, draggable,
 *  shrinkable. colours are NOT hardcoded per state anymore:
 *  the prism engine in client.js writes CSS variables at 60fps
 *  and everything in here just consumes them.
 *
 *  heads up: ServiceNow's SCSS compiler is old and quietly eats
 *  some modern blocks (glass backdrop-filter+saturate combos,
 *  calc*var inside drop-shadow, grayscale(0.5)...). anything it
 *  cant digest lives in a <style> tag inside template.html
 *  instead - dont move those back here, you'll loose them.
 * ============================================================ */

/* ============================================================
 *  Root - R1.3 small floating mark, default top-left
 * ============================================================ */
.netra-root {
    position: fixed;
    left: 18px;
    top: 18px;
    z-index: 9999;
    font-family: 'Google Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    /* R8.1 - PRISM TOKENS. client.js rewrites every one of these at up
       to 60fps (state hue + speech-reactive modulation). The values
       here are only the first-paint fallback (idle emerald). All colour
       below should consume these vars, never hardcode a state colour. */
    --netra-hue: 152;
    --netra-amp: 0;
    --iris-bright: #aef0d0;
    --iris-mid:    #2eb858;
    --iris-dark:   #0a4a25;
    --iris-deep:   #021a0d;
    --core-mid:    #aef0d0;
    --eye-glow:    rgba(127, 255, 176, 0.55);
    --netra-glow-soft: rgba(127, 255, 176, 0.18);
    --nsg-0: #eafff2;
    --nsg-1: #7fffb0;
    --nsg-2: #2eb858;
    --nsg-3: #063d1f;
    --netra-aura1: rgba(64, 200, 255, 0.14);
    --netra-aura2: rgba(160, 90, 255, 0.11);
}
.netra-root * { box-sizing: border-box; }
.netra-root button { font-family: 'Google Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; }

/* Screen-reader-only */
.netra-sr-only {
    position: absolute !important;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0,0,0,0);
    white-space: nowrap;
    border: 0;
}

/* ============================================================
 *  ORB - the EYE (v13, inline SVG, 160x100)
 * ============================================================ */
.netra-orb {
    position: relative;
    /* R3 - 50% smaller (72 -> 36). Internal SVG viewBox stays 120x120, so
       every golden-ratio relationship inside the orb is preserved — only
       the outer rendered size is halved. */
    width: 36px;
    height: 36px;
    border: 0;
    cursor: grab;
    background: transparent;
    padding: 0;
    transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
                filter 0.35s ease,
                width 0.382s ease,        /* 1 - 1/phi seconds */
                height 0.382s ease;
    overflow: visible;
    /* R8.1 - the iris palette now lives on .netra-root and is written
       live by the prism engine; nothing is redefined here so the vars
       inherit straight through. */
}
.netra-orb:hover  { transform: scale(1.0618); }   /* 1 + 1/phi*0.1 */
.netra-orb:active { cursor: grabbing; transform: scale(0.95); }

/* R2.12.3 - SPEAKER-CONE PULSE. The whole SVG sphere breathes with the
   bass band — driven by --orb-pulse, a 0..1 value set per-frame from
   the lowest frequency bucket. Scale factor 0.18 -> 0.10 in R2.12.3
   so the orb doesn't bash into the voice ring on bass spikes. */
.netra-orb .netra-eye-svg {
    transition: transform 80ms cubic-bezier(0.22, 1, 0.36, 1);
    transform: scale(calc(1 + var(--orb-pulse, 0) * 0.10));
    transform-origin: 50% 50%;
    will-change: transform;
}

/* Shrunk mode - 36 / phi = 22.2 ~ 22 px (golden-ratio shrink from R3 base 36) */
.netra-shrunk .netra-orb {
    width: 22px;
    height: 22px;
}
/* R3.1 - kill ALL focus / outline rings on the orb. The default browser
   button focus outline (green rectangle) was leaking through because we
   only disabled :focus-visible, not :focus. */
.netra-orb,
.netra-orb:hover,
.netra-orb:active,
.netra-orb:focus,
.netra-orb:focus-visible,
.netra-orb:focus-within {
    outline: none !important;
    box-shadow: none;
    -webkit-tap-highlight-color: transparent;
}
.netra-orb:hover  { transform: scale(1.05); }
.netra-orb:active { transform: scale(0.98); }
.netra-orb:focus-visible {
    --eye-glow: rgba(138, 180, 248, 0.65);
}

.netra-eye-svg {
    width: 100%;
    height: 100%;
    display: block;
    overflow: visible;
    /* R2.5 golden-ratio drop shadow. The amp-driven bloom layer lives in
       the template <style> (SCSS compiler chokes on calc*var in shadows). */
    filter: drop-shadow(0 7.4px 12px var(--eye-glow, rgba(127, 255, 176, 0.4)));
}

/* R2.5 - Halo pulses on a phi-second cycle (1.618 * 2.236 = ~3.618 s) */
.netra-eye-halo {
    transform-origin: 60px 60px;
    transform-box: view-box;
    animation: netra-halo-pulse 3.618s ease-in-out infinite;
}
@keyframes netra-halo-pulse {
    0%, 100% { opacity: 0.62;  transform: scale(0.945); }   /* 1/phi  + halo at rest */
    50%      { opacity: 1;     transform: scale(1.083); }   /* breathing out */
}

/* Pupil breathes on the same phi cycle (in sync with halo) */
.netra-eye-pupil {
    transform-origin: 60px 60px;
    transform-box: view-box;
    animation: netra-pupil-breath 3.618s ease-in-out infinite;
}
@keyframes netra-pupil-breath {
    0%, 100% { transform: scale(1);    }
    50%      { transform: scale(1.083); }
}

/* Catchlight shimmer at golden-cycle (phi^2 = 2.618 s) */
.netra-eye-glint {
    animation: netra-glint-shimmer 2.618s ease-in-out infinite;
}
@keyframes netra-glint-shimmer {
    0%, 100% { opacity: 0.92; }
    50%      { opacity: 0.65; }
}

/* R2.8.2 - audio-reactive voice ring (connected polygon waveform).
   Single polygon whose 24 vertices recompute from c.audioLevel.
   Stroke is the bright neon outline; fill is a translucent radial
   gradient that brightens just outside the sphere edge. */
.netra-voice-ring-group {
    pointer-events: none;
    opacity: 0.95;
    animation: voice-ring-fade-in 0.4s ease-out forwards;
}
.netra-voice-ring-fill {
    transition: opacity 0.3s ease;
    opacity: 0.7;
}
.netra-voice-ring-stroke {
    transition: stroke-width 0.18s ease, filter 0.3s ease;
    filter: drop-shadow(0 0 4px var(--eye-glow, rgba(160, 80, 240, 0.75))) drop-shadow(0 0 10px var(--netra-glow-soft, rgba(190, 90, 235, 0.35))) drop-shadow(0 0 18px var(--netra-glow-soft, rgba(255, 170, 80, 0.18)));
}
@keyframes voice-ring-fade-in {
    from { opacity: 0; }
    to   { opacity: 0.95; }
}

/* ============================================================
 *  R8.1 - PRISM PAINT HOOKS
 *  The SVG gradient stops and glow floods carry classes; the prism
 *  engine writes the matching vars on .netra-root each frame, so
 *  the whole aura family re-tints live with the voice.
 * ============================================================ */
.netra-root .nvg-core { stop-color: var(--nvg-core, rgba(139, 61, 240, 0.95)); }
.netra-root .nvg-mid  { stop-color: var(--nvg-mid,  rgba(190, 90, 235, 0.80)); }
.netra-root .nvg-hot  { stop-color: var(--nvg-hot,  rgba(255, 170,  80, 0.55)); }
.netra-root .nvg-edge { stop-color: var(--nvg-edge, rgba(160, 64, 232, 0.35)); }
.netra-root .nvs-a  { stop-color: var(--nvs-a, #6920b8); }
.netra-root .nvs-b  { stop-color: var(--nvs-b, #8b3df0); }
.netra-root .nvs-b2 { stop-color: var(--nvs-b, #c660ff); }
.netra-root .nvs-c  { stop-color: var(--nvs-c, #ffb84d); }
.netra-root .nvs-d  { stop-color: var(--nvs-d, #5a1aa0); }
.netra-root .nfl-1 { flood-color: var(--nfl-1, #a050f0); }
.netra-root .nfl-2 { flood-color: var(--nfl-2, #be5aeb); }
.netra-root .nfl-3 { flood-color: var(--nfl-3, #ffaa50); }
.netra-root .nfl-4 { flood-color: var(--nfl-4, #8b3df0); }
/* dev-console mini-eye iris follows the live hue too */
.netra-root .ndgi-1 { stop-color: var(--iris-bright, #7fffb0); }
.netra-root .ndgi-2 { stop-color: var(--iris-mid,    #2eb858); }
.netra-root .ndgi-3 { stop-color: var(--iris-deep,   #021a0d); }

/* R8.1 - SPEAKING ECHO RINGS: three staggered circles expanding out
 * of the sphere while Netra talks, stroked with the live glow colour.
 * Amplitude lifts their peak opacity via --netra-amp. */
.netra-orb-echo {
    stroke: var(--eye-glow, rgba(140, 90, 240, 0.6));
    stroke-width: 1.4;
    opacity: 0;
    transform-origin: 60px 60px;
    transform-box: view-box;
}
.netra-state-speaking .netra-orb-echo-1 { animation: netra-echo-out 2.1s cubic-bezier(0.2, 0.6, 0.35, 1) infinite; }
.netra-state-speaking .netra-orb-echo-2 { animation: netra-echo-out 2.1s cubic-bezier(0.2, 0.6, 0.35, 1) 0.7s infinite; }
.netra-state-speaking .netra-orb-echo-3 { animation: netra-echo-out 2.1s cubic-bezier(0.2, 0.6, 0.35, 1) 1.4s infinite; }
@keyframes netra-echo-out {
    0%   { transform: scale(1);    opacity: 0; }
    12%  { opacity: calc(0.38 + var(--netra-amp, 0) * 0.5); }
    100% { transform: scale(1.55); opacity: 0; }
}

/* While speaking, the halo pulses 1.32x..1.52x; the keyframe animation
   owns the transform, so don't set a static scale here. */
.netra-state-speaking .netra-eye-halo {
    transform-origin: 60px 60px;
    transform-box: view-box;
    animation: halo-pulse-speaking 1.2s ease-in-out infinite;
}
.netra-state-speaking .netra-voice-ring-fill   { opacity: 0.95; }
.netra-state-speaking .netra-voice-ring-stroke {
    stroke-width: 2.2;
    filter: drop-shadow(0 0 6px rgba(160, 80, 240, 0.90)) drop-shadow(0 0 16px rgba(190, 90, 235, 0.55)) drop-shadow(0 0 26px rgba(255, 170, 80, 0.30)) drop-shadow(0 0 38px rgba(139, 61, 240, 0.15));
}
@keyframes halo-pulse-speaking {
    0%, 100% { transform: scale(1.32); opacity: 0.85; }
    50%      { transform: scale(1.52); opacity: 1;    }
}

/* While listening the halo is only slightly larger - subtle activity. */
.netra-state-idle .netra-eye-halo {
    transform: scale(1.05);
    transform-origin: 60px 60px;
    transform-box: view-box;
}

/* The inscribed pentagram rotates SLOWLY - one full turn every 21 sec
   (the 7th Fibonacci number * 3, deliberately divisible by phi). */
.netra-eye-pentagram {
    transform-origin: 60px 60px;
    transform-box: view-box;
    animation: netra-pentagram-spin 21s linear infinite;
}
@keyframes netra-pentagram-spin {
    from { transform: rotate(0deg); }
    to   { transform: rotate(360deg); }
}

.netra-eye-glow {
    transition: stroke 0.4s ease, stroke-width 0.4s ease;
    filter: blur(4px);
}

.netra-eye-iris {
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.netra-eye-iris-group {
    transform-origin: 80px 50px;
    transition: transform 0.35s ease;
}

.netra-eye-pupil {
    transition: transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.netra-eye-lid-top,
.netra-eye-lid-bottom {
    transition: transform 0.4s cubic-bezier(0.6, 0, 0.2, 1);
}

.netra-eye-glint,
.netra-eye-glint-small {
    transition: opacity 0.3s ease, fill 0.3s ease;
}

/* ============================================================
 *  States (R8.1) - the palettes are gone: the prism engine writes
 *  the hue live on .netra-root (idle emerald -> awaiting cyan ->
 *  thinking magenta churn -> speaking voice-modulated violet ->
 *  dormant dim violet -> error red). Only the per-state BEHAVIOUR
 *  (blinks, pupil scale, spins, shakes) remains here.
 * ============================================================ */
.netra-state-idle .netra-eye-glow {
    animation: eye-glow-pulse 3s ease-in-out infinite;
}
.netra-state-idle .netra-eye-lid-top {
    animation: eye-blink-top 7s ease-in-out infinite;
}
.netra-state-idle .netra-eye-lid-bottom {
    animation: eye-blink-bottom 7s ease-in-out infinite;
}

/* State - AWAITING (cyan capture via prism engine) */
.netra-state-awaiting .netra-eye-pupil {
    transform: scale(1.25);
}
.netra-state-awaiting .netra-eye-lid-top {
    animation: eye-blink-top 7s ease-in-out infinite;
}
.netra-state-awaiting .netra-eye-lid-bottom {
    animation: eye-blink-bottom 7s ease-in-out infinite;
}

/* State - LISTENING (legacy alias of awaiting) */
.netra-state-listening .netra-eye-pupil {
    transform: scale(1.55);
}
.netra-state-listening .netra-eye-glow {
    animation: eye-glow-fast 0.7s ease-in-out infinite;
}
.netra-state-listening .netra-eye-lid-top {
    animation: eye-blink-top 7s ease-in-out infinite;
}
.netra-state-listening .netra-eye-lid-bottom {
    animation: eye-blink-bottom 7s ease-in-out infinite;
}

/* State - THINKING (magenta churn via prism engine) */
.netra-state-thinking .netra-eye-pupil {
    animation: pupil-breath 1.5s ease-in-out infinite;
}
.netra-state-thinking .netra-eye-iris-group {
    animation: eye-iris-spin 1.6s linear infinite;
}

/* State - SPEAKING (voice-modulated hue via prism engine) */
.netra-state-speaking .netra-eye-iris {
    animation: eye-iris-breathe 1.5s ease-in-out infinite;
    transform-box: fill-box;
    transform-origin: center;
}
.netra-state-speaking .netra-eye-lid-top {
    animation: eye-blink-top 7s ease-in-out infinite;
}
.netra-state-speaking .netra-eye-lid-bottom {
    animation: eye-blink-bottom 7s ease-in-out infinite;
}

/* ============================================================
 *  State - DORMANT (R3.2 - alive but resting: violet breathing glow)
 *
 *  The previous attempt set CSS variables to violet but the dark
 *  eyelid (opacity 0.88) + dark core gradient still made the orb
 *  read as a solid black blob. R3.2 overrides:
 *    - --core-mid (sphere base colour) to violet
 *    - --eye-glow strongly violet
 *    - eyelid opacity dropped from 0.88 to 0.18 so the iris breathes
 *      through, not behind a black curtain
 *    - iris/pupil colours guaranteed-violet via inline fill override
 *      using filter chains (SVG paint-order respects this)
 * ============================================================ */
/* Eyelids almost OPEN in dormant — was 0.88 covering, now 0.18 hinting */
.netra-state-dormant .netra-eye-lid-top     { opacity: 0.18; }
.netra-state-dormant .netra-eye-lid-bottom  { opacity: 0.18; }
.netra-state-dormant .netra-eye-glint       { opacity: 0; }
.netra-state-dormant .netra-eye-glint-small { opacity: 0; }
.netra-state-dormant .netra-eye-pentagram   { opacity: 0; }

/* Dormant tint now follows the prism vars (engine dims sat + holds violet) */
.netra-state-dormant .netra-eye-iris {
    fill: var(--iris-mid, #8b4dc8);
    animation: netra-dormant-breathe 4.2s ease-in-out infinite;
    transform-box: fill-box;
    transform-origin: center;
    opacity: 0.85;
}
.netra-state-dormant .netra-eye-pupil {
    fill: var(--iris-deep, #2a1560);
    animation: netra-dormant-pupil 4.2s ease-in-out infinite;
    transform-box: fill-box;
    transform-origin: center;
    opacity: 0.9;
}
.netra-state-dormant .netra-eye-halo {
    animation: netra-dormant-halo 4.2s ease-in-out infinite;
    transform-origin: 60px 60px;
    transform-box: view-box;
}
.netra-state-dormant .netra-eye-sphere {
    fill: var(--core-mid, #b48af0) !important;
    opacity: 0.55;
}
@keyframes netra-dormant-breathe {
    0%, 100% { opacity: 0.70; transform: scale(1); }
    50%      { opacity: 1.00; transform: scale(1.06); }
}
@keyframes netra-dormant-pupil {
    0%, 100% { opacity: 0.75; transform: scale(0.95); }
    50%      { opacity: 1.00; transform: scale(1.02); }
}
@keyframes netra-dormant-halo {
    0%, 100% { opacity: 0.35; transform: scale(0.95); }
    50%      { opacity: 0.80; transform: scale(1.15); }
}

/* ============================================================
 *  State - ERROR (soft red via prism engine, gentle shake)
 * ============================================================ */
.netra-state-error .netra-orb {
    animation: eye-shake 0.45s ease;
}

/* ============================================================
 *  State - BOOT
 * ============================================================ */
.netra-state-boot .netra-orb { filter: brightness(0.85); }
.netra-state-boot .netra-eye-iris-group { opacity: 0.7; }

/* ============================================================
 *  Keyframes
 * ============================================================ */
@keyframes eye-glow-pulse {
    0%   { stroke-width: 1.5; opacity: 0.6; }
    50%  { stroke-width: 3;   opacity: 1;   }
    100% { stroke-width: 1.5; opacity: 0.6; }
}

@keyframes eye-glow-fast {
    0%   { stroke-width: 2; opacity: 0.6; }
    50%  { stroke-width: 5; opacity: 1;   }
    100% { stroke-width: 2; opacity: 0.6; }
}

@keyframes eye-iris-spin {
    from { transform: rotate(0deg);   }
    to   { transform: rotate(360deg); }
}

@keyframes eye-iris-breathe {
    0%   { transform: scale(1);    }
    50%  { transform: scale(1.09); }
    100% { transform: scale(1);    }
}

@keyframes eye-shake {
    0%   { transform: translateX(0); }
    20%  { transform: translateX(-5px) rotate(-1.5deg); }
    50%  { transform: translateX(5px)  rotate(1.5deg);  }
    80%  { transform: translateX(-3px) rotate(-0.8deg); }
    100% { transform: translateX(0); }
}

@keyframes eye-blink-top {
    0%   { transform: translateY(0); }
    94%  { transform: translateY(0); }
    97%  { transform: translateY(60px); }
    100% { transform: translateY(0); }
}

@keyframes eye-blink-bottom {
    0%   { transform: translateY(0); }
    94%  { transform: translateY(0); }
    97%  { transform: translateY(-60px); }
    100% { transform: translateY(0); }
}

/* ============================================================
 *  Initial-gesture gate
 * ============================================================ */
/* R8.1 - glass gate with a live prism border: the first thing a sighted
   helper sees, so it now carries the same living colour as the orb. */
.netra-gate {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    padding: 16px 22px 16px 18px;
    background: rgba(18, 14, 28, 0.86);
    -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);
    border: 2px solid var(--iris-mid, #4285F4);
    border-radius: 18px;
    box-shadow: 0 14px 40px var(--netra-glow-soft, rgba(66, 133, 244, 0.28)),
                inset 0 1px 0 rgba(255, 255, 255, 0.08);
    color: #f0eafc;
    cursor: pointer;
    transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.5s ease;
    max-width: 340px;
    text-align: left;
    animation: gate-in 0.3s ease;
}
.netra-gate:hover {
    transform: translateY(-2px);
    box-shadow: 0 18px 50px var(--eye-glow, rgba(66, 133, 244, 0.36));
}
.netra-gate:focus-visible {
    outline: 3px solid var(--iris-bright, #4285F4);
    outline-offset: 3px;
}

.netra-gate-icon {
    color: var(--iris-bright, #4285F4);
    display: inline-flex;
    flex: none;
    filter: drop-shadow(0 0 10px var(--netra-glow-soft, rgba(66, 133, 244, 0.4)));
}
.netra-gate-text {
    display: flex;
    flex-direction: column;
    line-height: 1.35;
}
.netra-gate-text strong { font-size: 15px; font-weight: 600; color: #ffffff; }
.netra-gate-text span   { font-size: 13px; color: #b4a9d6; }

@keyframes gate-in {
    from { opacity: 0; transform: translateY(8px); }
    to   { opacity: 1; transform: translateY(0); }
}

/* ============================================================
 *  Transcript card (sighted-helper preview)
 * ============================================================ */
.netra-card {
    width: 360px;
    max-width: calc(100vw - 56px);
    background: linear-gradient(160deg, rgba(36, 36, 56, 0.96), rgba(18, 18, 28, 0.96));
    border: 1px solid rgba(127, 255, 176, 0.25);
    border-radius: 14px;
    padding: 14px 16px;
    box-shadow: 0 14px 40px rgba(0, 0, 0, 0.4), 0 0 18px rgba(127, 255, 176, 0.18);
    /* R3.1 - removed `saturate(140%)` from backdrop-filter. Sass parser
       was treating it as the built-in Sass color function `saturate($color,
       $amount)` and complaining about the missing $color argument
       (Performance Analyzer flagged 2 errors). Drop-only fix; the blur
       still gives the glass effect. */
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    color: #ebedf2;
    display: flex;
    flex-direction: column;
    gap: 10px;
    animation: card-in 0.25s ease;
    transition: box-shadow 0.35s ease, border-color 0.35s ease;
}
.netra-card-speaking {
    box-shadow: 0 14px 40px rgba(0, 0, 0, 0.4), 0 0 26px rgba(127, 255, 176, 0.55);
    border-color: rgba(127, 255, 176, 0.6);
}
.netra-card-meta {
    display: flex;
    gap: 8px;
    color: #6b7178;
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 9.5px;
    letter-spacing: 0.04em;
    padding-top: 4px;
    border-top: 1px solid rgba(255,255,255,0.05);
}
.netra-card-meta span:not(:last-child)::after {
    content: '·';
    margin-left: 8px;
    color: rgba(255,255,255,0.15);
}
/* R2.4 - clickable link fallback when popup blocked */
.netra-card-link {
    display: inline-block;
    margin-top: 8px;
    padding: 8px 12px;
    background: rgba(127, 255, 176, 0.18);
    color: #aef0d0 !important;
    border: 1px solid rgba(127, 255, 176, 0.4);
    border-radius: 8px;
    text-decoration: none;
    font-size: 12px;
    font-weight: 600;
    transition: background 0.15s ease;
    word-break: break-all;
}
.netra-card-link:hover {
    background: rgba(127, 255, 176, 0.3);
    text-decoration: none;
}
@keyframes card-in {
    from { opacity: 0; transform: translateY(6px); }
    to   { opacity: 1; transform: translateY(0); }
}
.netra-card-row {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    font-size: 13px;
    line-height: 1.45;
}
.netra-card-label {
    flex: none;
    font-size: 9.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #9aa0a6;
    padding-top: 3px;
    width: 42px;
}
.netra-card-row-bot .netra-card-label { color: #a5d6a7; }
.netra-card-text {
    color: #ebedf2;
    word-break: break-word;
    line-height: 1.5;
    font-size: 13px;
}
.netra-card-row-bot .netra-card-text {
    color: #ffffff;
}

/* ============================================================
 *  DEV PANEL (v13 - glassmorphic console)
 * ============================================================ */
/* R2.12 — VS CODE DARK+ AESTHETIC overrides the glassmorphic look.
   Palette: editor.background=#1e1e1e, sideBar.background=#252526,
   statusBar.background=#007acc, foreground=#cccccc, accent=#0e639c. */
.netra-dev {
    position: fixed;
    top: 18px;
    left: 100px;
    z-index: 100000;
    width: 460px;
    max-width: 96vw;
    max-height: 88vh;
    overflow: hidden;
    color: #cccccc;
    /* R8.2 - compiler-safe base; the glass upgrade (backdrop blur, hue
       border) is layered from the template <style> tag which the SCSS
       compiler never sees. */
    background: #1e1e1e;
    border: 1px solid #3a2a55;
    border-radius: 10px;
    padding: 0;                          /* tabs + status bar are flush */
    font-size: 12px;
    line-height: 1.45;
    font-family: 'JetBrains Mono', 'Cascadia Code', 'Consolas', monospace;
    box-shadow: 0 24px 64px -12px rgba(0, 0, 0, 0.75), 0 0 0 1px rgba(139,61,240,0.12), 0 8px 30px -8px rgba(139,61,240,0.25);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}
/* animated prism hairline across the very top of the console */
.netra-dev::before {
    content: '';
    display: block;
    height: 2px;
    flex: none;
    background: linear-gradient(90deg,
        var(--netra-aura1, rgba(64,200,255,0.8)),
        var(--eye-glow, rgba(139,61,240,0.9)),
        var(--netra-aura2, rgba(160,90,255,0.8)),
        var(--eye-glow, rgba(139,61,240,0.9)),
        var(--netra-aura1, rgba(64,200,255,0.8)));
    background-size: 300% 100%;
    animation: netra-hairline-flow 8s linear infinite;
}
@keyframes netra-hairline-flow {
    from { background-position: 0% 0; }
    to   { background-position: 300% 0; }
}
.netra-dev > .netra-dev-body {
    flex: 1 1 auto;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 6px 12px 8px;
}
.netra-dev > .netra-dev-body::-webkit-scrollbar { width: 10px; }
.netra-dev > .netra-dev-body::-webkit-scrollbar-track { background: #1e1e1e; }
.netra-dev > .netra-dev-body::-webkit-scrollbar-thumb { background: #424242; border-radius: 4px; }
.netra-dev > .netra-dev-body::-webkit-scrollbar-thumb:hover { background: #4e4e4e; }

/* Tab bar (VS Code editor tabs) */
.netra-dev-tabs {
    display: flex;
    background: #252526;
    border-bottom: 1px solid #3c3c3c;
    flex: none;
    user-select: none;
}
.netra-dev-tab {
    flex: 1;
    padding: 8px 6px;
    text-align: center;
    color: #969696;
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.02em;
    cursor: pointer;
    border-right: 1px solid #3c3c3c;
    transition: background 0.12s ease, color 0.12s ease;
}
.netra-dev-tab:last-child { border-right: none; }
.netra-dev-tab:hover { background: #2a2d2e; color: #cccccc; }
.netra-dev-tab.active {
    background: #1e1e1e;
    color: #ffffff;
    /* R8.1 - the active-tab accent follows the live prism hue */
    border-top: 2px solid var(--iris-mid, #8b3df0);
    padding-top: 6px;
}

/* Status bar (R5 - Netra violet gradient, was flat VS Code blue #007acc) */
.netra-dev-statusbar {
    background: linear-gradient(90deg, #5a1aa0 0%, #7a2ecc 45%, #8b3df0 100%);
    color: #ffffff;
    padding: 3px 12px;
    font-size: 10.5px;
    display: flex;
    gap: 16px;
    flex: none;
    border-top: 1px solid rgba(198,96,255,0.45);
    align-items: center;
}
.netra-dev-statusbar .seg { display: inline-flex; align-items: center; gap: 5px; }
.netra-dev-statusbar .seg + .seg::before {
    content: '';
    display: inline-block;
    width: 1px;
    height: 12px;
    background: rgba(255,255,255,0.3);
    margin-right: 6px;
}
.netra-dev-statusbar .seg.err   { background: #c72e0f; padding: 0 6px; margin: -3px 0; }
.netra-dev-statusbar .seg.warn  { color: #ffd34d; }
.netra-dev-statusbar .seg-key   {
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.08em;
    opacity: 0.75;
    text-transform: uppercase;
}
.netra-dev-statusbar .seg-val   { font-weight: 600; }

/* R2.12.2 - tighten the dev panel header (IDLE / AWAKE / hide pills) */
/* R5 - subtle violet-tinted header to carry the Netra brand */
.netra-dev-head {
    padding: 6px 10px 8px;
    gap: 6px;
    background: linear-gradient(180deg, #2a2140 0%, #241b33 60%, #252526 100%);
    border-bottom: 1px solid #3c3c3c;
}

/* R5 - product identity in the developer console header */
.netra-dev-brand {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    flex: 1;
    min-width: 0;
}
.netra-dev-glyph {
    width: 18px;
    height: 18px;
    flex: none;
    filter: drop-shadow(0 0 5px var(--eye-glow, rgba(139,61,240,0.55)));
}
.netra-dev-glyph-live { animation: netra-glyph-spin 6s linear infinite; transform-origin: 16px 16px; }
@keyframes netra-glyph-spin { to { transform: rotate(360deg); } }
.netra-dev-word {
    font-family: 'Google Sans', 'Inter', -apple-system, 'Segoe UI', sans-serif;
    font-size: 12.5px;
    font-weight: 700;
    letter-spacing: 0.16em;
    background: linear-gradient(90deg, #d8c8ff 0%, #c660ff 55%, #7fffb0 100%);
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: #d8c8ff;
}
.netra-dev-badge-vr {
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 8.5px;
    font-weight: 700;
    letter-spacing: 0.1em;
    color: #ffd7a0;
    background: rgba(255,184,77,0.14);
    border: 1px solid rgba(255,184,77,0.4);
    border-radius: 999px;
    padding: 1px 7px;
    white-space: nowrap;
}
.netra-dev-pill {
    padding: 2px 8px;
    border-radius: 4px;
    font-size: 9.5px;
    line-height: 1.4;
}
.netra-dev-x {
    background: transparent;
    border: 1px solid #3c3c3c;
    border-radius: 4px;
    padding: 2px 8px;
    font-size: 10px;
    color: #969696;
}
.netra-dev-x:hover { background: #3a1f66; color: #ffffff; border-color: #8b3df0; }
.netra-dev section { margin: 8px 0; }
/* R2.12 — VS Code "Command Palette" / quickpick button style.
   Solid dark with subtle border. Hover lifts background to #094771
   (VS Code's selected-list-row colour). */
.netra-dev button {
    background: #2d2d2d;
    color: #cccccc;
    border: 1px solid #3c3c3c;
    border-radius: 3px;
    padding: 4px 9px;
    cursor: pointer;
    font-family: inherit;
    font-size: 11px;
    line-height: 1.2;
    font-weight: 500;
    letter-spacing: 0;
    transition: background 0.1s ease, border-color 0.1s ease, color 0.1s ease;
}
/* R5 - hover/active lift to Netra violet (was VS Code blue #094771/#007acc) */
.netra-dev button:hover:not(:disabled) {
    background: #3a1f66;
    color: #ffffff;
    border-color: #8b3df0;
}
.netra-dev button:active:not(:disabled) { background: #4a2a8a; }
.netra-dev button:disabled { opacity: 0.4; cursor: not-allowed; }
.netra-dev button.primary {
    background: #6920b8;
    color: #ffffff;
    border-color: #6920b8;
}
.netra-dev button.primary:hover:not(:disabled) {
    background: #8b3df0;
    border-color: #8b3df0;
}

/* Pane visibility — driven by c.devTab */
.netra-dev-pane { display: none; }
.netra-dev-pane.active { display: block; }

/* Section headers inside panes (VS Code Outline-view style) */
.netra-dev-pane h4 {
    color: #cccccc;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin: 12px 0 6px;
    padding-bottom: 4px;
    border-bottom: 1px solid #3c3c3c;
}
.netra-dev-pane h4:first-child { margin-top: 6px; }

.netra-dev-head {
    display: flex;
    align-items: center;
    gap: 8px;
    padding-bottom: 10px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    margin-bottom: 0;
    cursor: grab;   /* R1.3 - draggable header */
    user-select: none;
}
.netra-dev-head:active { cursor: grabbing; }
/* R2.5 - NETRA wordmark removed; version pill stretches to fill the gap */
.netra-dev-ver {
    flex: 1;
    color: #9aa0a6;
    font-size: 9.5px;
    font-weight: 500;
    margin-left: 2px;
    letter-spacing: 0.05em;
    -webkit-text-fill-color: #9aa0a6;
}

/* Animated live mic indicator */
.netra-dev-live {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #5f6368;
    flex: none;
    transition: background 0.25s ease;
    box-shadow: 0 0 0 0 rgba(129, 201, 149, 0);
}
.netra-dev-live.on {
    background: #81c995;
    animation: netra-live-pulse 1.8s ease-in-out infinite;
}
@keyframes netra-live-pulse {
    0%   { box-shadow: 0 0 0 0   rgba(129, 201, 149, 0.6); }
    50%  { box-shadow: 0 0 0 6px rgba(129, 201, 149, 0);   }
    100% { box-shadow: 0 0 0 0   rgba(129, 201, 149, 0.6); }
}

.netra-dev-pill {
    background: rgba(255, 255, 255, 0.07);
    border-radius: 999px;
    padding: 3px 9px;
    font-size: 9.5px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #ebedf2;
    transition: background 0.25s ease, color 0.25s ease, box-shadow 0.25s ease;
}
.netra-dev-pill-idle      { background: rgba(138,180,248,0.18); color: #aecbfa; }
.netra-dev-pill-listening { background: rgba(255,118,118,0.20); color: #ff9b9b; box-shadow: 0 0 14px rgba(255,118,118,0.35); }
.netra-dev-pill-awaiting  { background: rgba(174,213,129,0.20); color: #c5e1a5; box-shadow: 0 0 14px rgba(174,213,129,0.35); }
.netra-dev-pill-thinking  { background: rgba(249,171,0,0.22);   color: #ffd54f; }
.netra-dev-pill-speaking  { background: rgba(129,201,149,0.22); color: #a5d6a7; box-shadow: 0 0 14px rgba(129,201,149,0.35); }
.netra-dev-pill-paused    { background: rgba(255,255,255,0.08); color: #c4c7c5; }
.netra-dev-pill-dormant   { background: rgba(255,255,255,0.08); color: #9aa0a6; }
.netra-dev-pill-error     { background: rgba(255,118,118,0.22); color: #ff9b9b; }
.netra-dev-pill-boot      { background: rgba(255,255,255,0.08); color: #c4c7c5; }
.netra-dev-pill-mode      { background: rgba(255,255,255,0.06); color: #9aa0a6; }
.netra-dev-pill-mode.on   { background: rgba(129,201,149,0.20); color: #a5d6a7; }

.netra-dev-x {
    font-size: 10px;
    padding: 3px 8px !important;
    opacity: 0.7;
}
.netra-dev-x:hover { opacity: 1; }

.netra-dev-status,
.netra-dev-transcript {
    display: flex;
    flex-direction: column;
    gap: 1px;
    background: rgba(0, 0, 0, 0.18);
    border-radius: 8px;
    padding: 6px 10px;
}
.netra-dev-status div,
.netra-dev-transcript div {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 10px;
    padding: 3px 0;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03);
}
.netra-dev-status div:last-child,
.netra-dev-transcript div:last-child { border-bottom: 0; }
.netra-dev-status div span:first-child,
.netra-dev-transcript div span:first-child {
    color: #9aa0a6;
    font-size: 10.5px;
    font-weight: 400;
    letter-spacing: 0.02em;
    flex: none;
}
.netra-dev-status div b,
.netra-dev-status div em,
.netra-dev-transcript div b,
.netra-dev-transcript div em {
    color: #ebedf2;
    font-weight: 500;
    font-style: normal;
    text-align: right;
    word-break: break-word;
    font-family: 'JetBrains Mono', 'Consolas', 'Monaco', monospace;
    font-size: 10.5px;
}
.netra-dev-status div em.on,
.netra-dev-transcript div em.on {
    color: #f9ab00;
    text-shadow: 0 0 8px rgba(249, 171, 0, 0.4);
}
.netra-dev-status div b.on,
.netra-dev-transcript div b.on {
    color: #a5d6a7;
    text-shadow: 0 0 8px rgba(129, 201, 149, 0.4);
}
.netra-dev-status div b.l-err,
.netra-dev-transcript div b.l-err { color: #ff7676; }

.netra-dev-tx-row em {
    flex: 1;
    text-align: left;
    margin-left: 10px;
}

.netra-dev-input {
    display: flex;
    gap: 6px;
}
.netra-dev-input input {
    flex: 1;
    background: rgba(0, 0, 0, 0.32);
    color: #ebedf2;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
    padding: 7px 10px;
    font-size: 12px;
    font-family: 'Inter', 'Segoe UI', sans-serif;
    outline: none;
    transition: border 0.15s ease, box-shadow 0.15s ease;
}
.netra-dev-input input::placeholder { color: #6b7178; }
.netra-dev-input input:focus {
    border-color: rgba(138, 180, 248, 0.6);
    box-shadow: 0 0 0 3px rgba(138, 180, 248, 0.12);
}

.netra-dev-actions {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 6px;
}
.netra-dev-actions button { white-space: nowrap; }

/* R1.2 - LIVE MIC LEVEL METER */
.netra-mic-meter {
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 8px;
    padding: 8px 10px;
}
.netra-mic-meter-label {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #9aa0a6;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: 6px;
}
.netra-mic-meter-status {
    padding: 2px 7px;
    border-radius: 999px;
    font-size: 8.5px;
    background: rgba(255,255,255,0.06);
    color: #c4c7c5;
}
.netra-mic-meter-status.on {
    background: rgba(129, 201, 149, 0.25);
    color: #a5d6a7;
    box-shadow: 0 0 10px rgba(129, 201, 149, 0.4);
}
.netra-mic-meter-status.l-err {
    background: rgba(255, 118, 118, 0.2);
    color: #ff9b9b;
}
.netra-mic-meter-peak {
    margin-left: auto;
    color: #6b7178;
    font-weight: 400;
    text-transform: none;
    letter-spacing: 0;
}
.netra-mic-meter-track {
    height: 10px;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 5px;
    overflow: hidden;
    position: relative;
}
.netra-mic-meter-fill {
    height: 100%;
    background: linear-gradient(90deg, #6dd882 0%, #ffe082 60%, #ff7676 95%);
    border-radius: 5px;
    transition: width 0.08s linear;
    box-shadow: 0 0 8px rgba(129, 201, 149, 0.5);
}
.netra-mic-meter-test {
    margin-top: 8px;
    display: flex;
    align-items: center;
    gap: 8px;
}
.netra-mic-meter-test button {
    background: linear-gradient(180deg, #3a3d49 0%, #2c2f3a 100%);
    color: #ebedf2;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 6px;
    padding: 5px 10px;
    font-size: 10.5px;
    cursor: pointer;
    font-family: inherit;
}
.netra-mic-meter-test button:disabled { opacity: 0.45; cursor: not-allowed; }
.netra-mic-meter-test em {
    color: #aecbfa;
    font-size: 10px;
    font-style: italic;
}

/* R1 - Real-time graphs */
.netra-dev-graphs {
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.netra-graph-card {
    background: rgba(0, 0, 0, 0.25);
    border: 1px solid rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    padding: 8px 10px;
}
.netra-graph-title {
    color: #9aa0a6;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: 0.08em;
    margin-bottom: 4px;
    text-transform: uppercase;
}
.netra-graph-sub {
    color: #6b7178;
    font-weight: 400;
    text-transform: none;
    letter-spacing: 0;
}
/* R2.8 - inline numeric labels on graphs */
.netra-graph-title { display: flex; align-items: baseline; gap: 6px; }
.netra-graph-stats {
    margin-left: auto;
    color: #ebedf2;
    font-weight: 600;
    font-size: 9px;
    text-transform: none;
    letter-spacing: 0;
    font-family: 'JetBrains Mono', 'Consolas', monospace;
}
.netra-graph-dim { color: #6b7178; font-weight: 400; }
.netra-graph-svg {
    width: 100%;
    height: 40px;
    display: block;
}
.netra-graph-bars { padding-bottom: 6px; }
.netra-bar-row {
    display: grid;
    grid-template-columns: 90px 1fr 24px;
    gap: 6px;
    align-items: center;
    font-size: 10px;
    padding: 2px 0;
    color: #c4c7c5;
    font-family: 'JetBrains Mono', 'Consolas', monospace;
}
.netra-bar-label {
    color: #aecbfa;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.netra-bar-track {
    height: 6px;
    background: rgba(255, 255, 255, 0.06);
    border-radius: 3px;
    overflow: hidden;
}
.netra-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, #8ab4f8, #c39bd3);
    border-radius: 3px;
    transition: width 0.4s ease;
}
.netra-bar-count {
    text-align: right;
    color: #ebedf2;
}
.netra-bar-empty {
    color: #6b7178;
    font-style: italic;
    text-align: center;
    padding: 6px 0;
    font-size: 10.5px;
}

/* R2.2 - voice training */
.netra-dev-train {
    background: rgba(0, 0, 0, 0.28);
    border: 1px solid rgba(255, 255, 255, 0.06);
    border-radius: 8px;
    padding: 8px 10px;
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.netra-train-title {
    color: #aecbfa;
    font-size: 9.5px;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    display: flex;
    align-items: center;
    gap: 8px;
}
.netra-train-sub {
    color: #6b7178;
    font-weight: 400;
    letter-spacing: 0;
    text-transform: none;
    margin-left: auto;
}
.netra-train-row {
    display: flex;
    align-items: center;
    gap: 6px;
}
.netra-train-row input {
    flex: 1;
    background: rgba(0, 0, 0, 0.34);
    color: #ebedf2;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 6px;
    padding: 5px 8px;
    font-size: 11px;
    font-family: inherit;
    outline: none;
    min-width: 0;
}
.netra-train-row input::placeholder { color: #6b7178; }
.netra-train-row button {
    background: linear-gradient(180deg, #3a3d49 0%, #2c2f3a 100%);
    color: #ebedf2;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 6px;
    padding: 5px 10px;
    font-size: 10px;
    cursor: pointer;
    flex: none;
    font-family: inherit;
}
.netra-train-row button:disabled { opacity: 0.4; cursor: not-allowed; }
.netra-train-half { flex: 1; }
.netra-train-arrow {
    color: #aecbfa;
    font-size: 12px;
    flex: none;
}
.netra-train-aliases {
    max-height: 80px;
    overflow: auto;
    padding: 4px 0;
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 9.5px;
}
.netra-train-alias {
    padding: 1px 0;
    color: #c4c7c5;
}
.netra-train-alias-misheard { color: #ff9b9b; }
.netra-train-alias-arrow    { color: #6b7178; padding: 0 4px; }
.netra-train-alias-intended { color: #a5d6a7; }
.netra-train-clear {
    background: rgba(255, 118, 118, 0.12);
    color: #ff9b9b;
    border: 1px solid rgba(255, 118, 118, 0.2);
    border-radius: 6px;
    padding: 4px 8px;
    font-size: 9.5px;
    cursor: pointer;
    align-self: flex-start;
    font-family: inherit;
}
.netra-train-clear:hover {
    background: rgba(255, 118, 118, 0.2);
}

/* R1.4 - last-turn tool trace */
.netra-trace-row {
    display: grid;
    grid-template-columns: 20px 1fr 24px 32px;
    gap: 4px;
    align-items: center;
    font-size: 10px;
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    padding: 2px 0;
}
.netra-trace-step {
    background: rgba(127,255,176,0.18);
    color: #a5d6a7;
    border-radius: 3px;
    text-align: center;
    font-weight: 700;
    font-size: 9px;
    padding: 1px 0;
}
.netra-trace-name {
    color: #aecbfa;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.netra-trace-arrow {
    color: #6b7178;
    text-align: right;
}
.netra-trace-ok {
    color: #a5d6a7;
    font-weight: 600;
    font-size: 9px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.netra-dev-voices label {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 10.5px;
    color: #9aa0a6;
}
.netra-dev-voices label span { flex: none; letter-spacing: 0.02em; }
.netra-dev-voices label select {
    flex: 1;
    background: rgba(0, 0, 0, 0.32);
    color: #ebedf2;
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 8px;
    padding: 5px 8px;
    font-size: 11px;
    font-family: 'Inter', 'Segoe UI', sans-serif;
    outline: none;
}

.netra-dev-log {
    background: rgba(0, 0, 0, 0.35);
    border: 1px solid rgba(255, 255, 255, 0.04);
    border-radius: 8px;
    padding: 8px 10px;
    max-height: 260px;
    overflow: auto;
    font-family: 'JetBrains Mono', 'Consolas', 'Monaco', monospace;
    font-size: 10.5px;
    line-height: 1.55;
}
.netra-dev-log-row {
    display: grid;
    grid-template-columns: 56px 50px 1fr;
    gap: 6px;
    padding: 1px 0;
    color: #c4c7c5;
    word-break: break-word;
}
.netra-dev-log-row .t { color: #6b7178; }
.netra-dev-log-row .l {
    color: #9aa0a6;
    text-transform: uppercase;
    font-size: 9.5px;
    letter-spacing: 0.04em;
}
.netra-dev-log-row .m { color: #e6e6ec; }
.netra-dev-log-row.l-err   .l,
.netra-dev-log-row.l-err   .m { color: #ff7676; }
.netra-dev-log-row.l-wake  .l { color: #34a853; }
.netra-dev-log-row.l-cmd   .l { color: #f9ab00; }
.netra-dev-log-row.l-dev   .l { color: #8ab4f8; }
.netra-dev-log-row.l-srv   .l { color: #d96570; }
.netra-dev-log-row.l-perm  .l { color: #c39bd3; }
.netra-dev-log-row.l-init  .l { color: #c4c7c5; }
.netra-dev-log-row.l-boot  .l { color: #81c995; }
.netra-dev-log-row.l-tts   .l { color: #4dd0e1; }
.netra-dev-log-row.l-conv  .l { color: #a5d6a7; }
.netra-dev-log-row.l-poll  .l { color: #80cbc4; opacity: 0.7; }
.netra-dev-log-row.l-mem   .l { color: #7dffb8; }
.netra-dev-log-row.l-warn  .l { color: #ffd34d; }
.netra-dev-log-row.l-lab   .l { color: #c39bd3; }
.netra-dev-log-row.l-rec   .l { color: #81c995; }
.netra-dev-log-row.l-mic   .l { color: #f9ab00; }
.netra-dev-log-row.l-barge .l { color: #ff8fab; }
.netra-dev-log-row.l-nav   .l { color: #80cbc4; }

.netra-dev-log-empty {
    color: #6b7178;
    font-style: italic;
    text-align: center;
    padding: 12px 0;
}

.netra-dev-badge {
    /* R3.1 - moved from top-left to BOTTOM-LEFT next to the orb. The orb
       lives at bottom-right via .netra-root, but its drag-saved position
       can be anywhere; the DEV badge sticks to the bottom-left corner
       (24px from each edge) so it's predictable and never far from the
       orb's typical resting area. */
    position: fixed;
    bottom: 24px;
    left: 24px;
    z-index: 100000;
    background: linear-gradient(160deg, rgba(36,36,56,0.92), rgba(18,18,28,0.92));
    /* R3.1 - removed `saturate(140%)` from backdrop-filter. Sass parser
       was treating it as the built-in Sass color function `saturate($color,
       $amount)` and complaining about the missing $color argument
       (Performance Analyzer flagged 2 errors). Drop-only fix; the blur
       still gives the glass effect. */
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    color: #d8c8ff;                                   /* R5 - Netra violet, was blue */
    border: 1px solid rgba(139,61,240,0.35);
    border-radius: 999px;
    padding: 6px 14px;
    font-family: 'JetBrains Mono', 'Consolas', 'Monaco', monospace;
    font-size: 10.5px;
    font-weight: 700;
    letter-spacing: 0.14em;
    cursor: pointer;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4), 0 0 14px -4px rgba(139,61,240,0.4);
    transition: transform 0.12s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}
.netra-dev-badge:hover {
    transform: translateY(-1px);
    border-color: rgba(198,96,255,0.6);
    box-shadow: 0 10px 24px rgba(0, 0, 0, 0.5), 0 0 20px -2px rgba(139,61,240,0.55);
}

/* ============================================================
 *  Responsive
 * ============================================================ */
@media (max-width: 480px) {
    .netra-root { right: 16px; bottom: 16px; }
    .netra-orb  { width: 36px; height: 36px; }   /* R3 - halved */
    .netra-dev  { width: calc(100vw - 24px); }
    .netra-dev-actions { grid-template-columns: repeat(2, 1fr); }
}

/* ============================================================
 *  R6 "Release X" - HUMAN TURN-TAKING SURFACES
 * ============================================================ */

/* Involuntary blink. The legacy eye-blink-top animation translated a
 * lid whose opacity is 0, so it never rendered; this dedicated layer
 * actually shows. Slow cycle awake, slightly quicker while thinking,
 * suppressed in dormant/error (the main lid or state already covers). */
.netra-eye-blink { pointer-events: none; }
.netra-state-idle .netra-eye-blink,
.netra-state-awaiting .netra-eye-blink,
.netra-state-listening .netra-eye-blink {
    animation: netra-blink 7.3s ease-in-out infinite;
}
.netra-state-thinking .netra-eye-blink {
    animation: netra-blink 4.7s ease-in-out infinite;
}
@keyframes netra-blink {
    0%, 95.4%, 100% { opacity: 0; }
    96.4%, 98.0%    { opacity: 0.92; }
}

/* Barge-in yield flash: one quick violet ripple through the halo the
 * moment Netra stops for the user - "go ahead, I am listening". */
.netra-barged .netra-eye-halo {
    animation: netra-yield-flash 0.7s ease-out 1;
}
.netra-barged .netra-eye-sphere {
    animation: netra-yield-dip 0.7s ease-out 1;
}
@keyframes netra-yield-flash {
    0%   { opacity: 1;    r: 58px; }
    30%  { opacity: 0.35; r: 66px; }
    100% { opacity: 1;    r: 58px; }
}
@keyframes netra-yield-dip {
    0%   { filter: brightness(1); }
    25%  { filter: brightness(1.5) saturate(0.7); }
    100% { filter: brightness(1); }
}

/* R8.1 - FULL CONTROL ticket badge in the dev console header */
.netra-dev-badge-fc {
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 8px;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: #a8ffd0;
    background: linear-gradient(90deg, rgba(46, 184, 88, 0.18), rgba(64, 200, 255, 0.14));
    border: 1px solid rgba(64, 230, 160, 0.55);
    border-radius: 999px;
    padding: 1px 7px;
    white-space: nowrap;
    text-shadow: 0 0 8px rgba(64, 230, 160, 0.45);
}

/* Monitor tab: turn-taking telemetry rows */
.netra-dev-status b.fc { color: #7dffb8; text-shadow: 0 0 8px rgba(64, 230, 160, 0.4); }
.netra-dev-status b.on { color: #c660ff; }

/* ============================================================
 *  R7 "Live" - LIQUID AURA + VOICE LAB + CHAT TAB
 * ============================================================ */

/* While she speaks, the sphere goes luminous and the mystic details
 * step back - the liquid aura is the star, GPT-Live style. */
.netra-state-speaking .netra-eye-pentagram { opacity: 0 !important; }
.netra-state-speaking .netra-eye-sphere    { filter: brightness(1.18) saturate(1.12); }
.netra-voice-blob-inner { mix-blend-mode: screen; }

/* Chat tab - conversation transcript */
.netra-dev-chat {
    max-height: 240px;
    overflow-y: auto;
    padding: 8px 10px;
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.netra-chat-row {
    display: grid;
    grid-template-columns: 44px 1fr auto;
    gap: 8px;
    align-items: baseline;
    font-size: 11px;
    line-height: 1.45;
}
.netra-chat-who {
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}
.chat-you   .netra-chat-who  { color: #7fffb0; }
.chat-netra .netra-chat-who  { color: #c660ff; }
.chat-you   .netra-chat-text { color: #d9e8dd; }
.chat-netra .netra-chat-text { color: #e6dcf5; }
.chat-sys {
    grid-template-columns: 1fr;
    text-align: center;
}
.chat-sys .netra-chat-who  { display: none; }
.chat-sys .netra-chat-text { color: #8a7fa8; font-style: italic; font-size: 10px; }
.chat-sys .netra-chat-time { display: none; }
.netra-chat-time { color: #5f5877; font-size: 9px; font-family: 'JetBrains Mono', monospace; }
.netra-chat-empty { color: #6f6790; font-size: 10.5px; font-style: italic; padding: 14px 0; text-align: center; }
.netra-chat-clear {
    align-self: flex-end;
    background: transparent;
    border: 1px solid #3a2a55;
    color: #9a8fc0;
    border-radius: 4px;
    font-size: 9.5px;
    padding: 2px 8px;
    cursor: pointer;
}
.netra-chat-clear:hover { border-color: #8b3df0; color: #d8c8ff; }

/* Voice Lab - neural voice picker + pace slider */
.netra-dev-voicelab {
    padding: 8px 10px;
    border-top: 1px solid #2d2440;
}
.netra-voicelab-title {
    font-family: 'JetBrains Mono', 'Consolas', monospace;
    font-size: 9.5px;
    font-weight: 700;
    letter-spacing: 0.1em;
    color: #b39ddb;
    margin-bottom: 6px;
}
.netra-voicelab-sub { color: #6f6790; font-weight: 400; margin-left: 6px; letter-spacing: 0.02em; }
.netra-voicelab-row {
    display: flex;
    align-items: center;
    gap: 8px;
    margin: 5px 0;
    font-size: 10.5px;
}
.netra-voicelab-row label { color: #8a7fa8; width: 38px; flex: none; font-size: 10px; }
.netra-voicelab-row select {
    flex: 1;
    background: #191024;
    color: #e6dcf5;
    border: 1px solid #3a2a55;
    border-radius: 4px;
    font-size: 10.5px;
    padding: 3px 6px;
}
.netra-voicelab-row input[type="range"] { flex: 1; accent-color: #8b3df0; }
.netra-voicelab-row em { color: #c660ff; font-style: normal; font-family: 'JetBrains Mono', monospace; font-size: 10px; width: 34px; }
.netra-voicelab-row button {
    background: linear-gradient(90deg, #5a1aa0, #8b3df0);
    border: none;
    color: #fff;
    border-radius: 4px;
    font-size: 10.5px;
    padding: 4px 12px;
    cursor: pointer;
}
.netra-voicelab-row button:hover { filter: brightness(1.15); }

/* ============================================================
 *  R8 - NETRA LIVE STAGE (dedicated /sp?id=netra_live page)
 *
 *  Full-screen live voice surface: the stage is a
 *  fixed overlay that covers the entire viewport (including the
 *  Service Portal chrome), a warm near-black canvas, one big
 *  organic blob breathing dead-centre, a quiet status line, a
 *  caption of the last thing heard, and two round controls.
 * ============================================================ */

/* On the dedicated page, hide the Service Portal shell entirely so
 * nothing but the stage shows. body gets .netra-live-body from JS. */
.netra-live-body #sp-page,
.netra-live-body .navbar,
.netra-live-body header.sp-navbar,
.netra-live-body .sp-navbar,
.netra-live-body sp-service-portal > header,
.netra-live-body #google_translate_element { display: none !important; }
.netra-live-body { background: #0d0714 !important; overflow: hidden !important; }

.netra-stage {
    position: fixed;
    inset: 0;
    z-index: 2147483000;
    display: flex;
    flex-direction: column;
    align-items: center;
    /* R8.1 - deep cosmic canvas; the tint rides the live hue */
    background:
        radial-gradient(120% 90% at 50% 34%, #2a1a45 0%, #1a1030 46%, #0f0a20 100%);
    color: #efe7ff;
    font-family: 'Google Sans', 'Inter', -apple-system, 'Segoe UI', sans-serif;
    -webkit-font-smoothing: antialiased;
    overflow: hidden;
}

/* soft drifting light so the room feels alive, not flat - now hue-locked */
.netra-stage::before {
    content: '';
    position: absolute;
    width: 90vmin; height: 90vmin;
    top: 50%; left: 50%;
    transform: translate(-50%, -54%);
    background: radial-gradient(circle, var(--netra-glow-soft, rgba(139,61,240,0.20)) 0%, var(--netra-aura1, rgba(127,255,176,0.06)) 42%, rgba(0,0,0,0) 70%);
    filter: blur(10px);
    animation: netra-stage-breathe 7s ease-in-out infinite;
    pointer-events: none;
}
@keyframes netra-stage-breathe {
    0%, 100% { transform: translate(-50%, -54%) scale(1);    opacity: 0.75; }
    50%      { transform: translate(-50%, -54%) scale(1.12); opacity: 1;    }
}

/* ------------------------------------------------------------
 * R8.1 - PRISM ROOM LAYERS
 * ------------------------------------------------------------ */
/* faint starfield, two parallax sheets drifting at different speeds */
.netra-stage-stars {
    position: absolute;
    inset: -20%;
    pointer-events: none;
    background-image:
        radial-gradient(1.2px 1.2px at 12% 22%, rgba(255,255,255,0.55) 50%, transparent 51%),
        radial-gradient(1px 1px at 34% 68%, rgba(255,255,255,0.35) 50%, transparent 51%),
        radial-gradient(1.4px 1.4px at 56% 12%, rgba(255,255,255,0.45) 50%, transparent 51%),
        radial-gradient(1px 1px at 72% 44%, rgba(255,255,255,0.30) 50%, transparent 51%),
        radial-gradient(1.2px 1.2px at 88% 76%, rgba(255,255,255,0.40) 50%, transparent 51%),
        radial-gradient(1px 1px at 22% 86%, rgba(255,255,255,0.28) 50%, transparent 51%),
        radial-gradient(1.3px 1.3px at 64% 90%, rgba(255,255,255,0.35) 50%, transparent 51%),
        radial-gradient(1px 1px at 44% 38%, rgba(255,255,255,0.25) 50%, transparent 51%),
        radial-gradient(1.1px 1.1px at 8% 54%, rgba(255,255,255,0.32) 50%, transparent 51%),
        radial-gradient(1px 1px at 94% 18%, rgba(255,255,255,0.30) 50%, transparent 51%);
    background-size: 46vmax 46vmax;
    animation: netra-stars-drift 160s linear infinite;
    opacity: 0.5;
}
@keyframes netra-stars-drift {
    from { transform: translate3d(0, 0, 0); }
    to   { transform: translate3d(-8vmax, -5vmax, 0); }
}

/* aurora ribbons - two huge blurred conic sweeps in hue-offset colours,
 * counter-rotating very slowly. Amplitude raises their alpha (the vars
 * are written with amp baked in), so the whole room swells when she
 * speaks. transform-only animation = GPU cheap. */
.netra-stage-aurora {
    position: absolute;
    width: 160vmax; height: 160vmax;
    top: 50%; left: 50%;
    margin: -80vmax 0 0 -80vmax;
    pointer-events: none;
    border-radius: 50%;
    filter: blur(60px) saturate(1.2);
    mix-blend-mode: screen;
    will-change: transform;
}
.netra-stage-aurora-1 {
    background: conic-gradient(from 0deg,
        transparent 0deg,
        var(--netra-aura1, rgba(64,200,255,0.14)) 40deg,
        transparent 110deg,
        var(--netra-aura2, rgba(160,90,255,0.11)) 180deg,
        transparent 250deg,
        var(--netra-aura1, rgba(64,200,255,0.10)) 300deg,
        transparent 360deg);
    animation: netra-aurora-spin 90s linear infinite;
}
.netra-stage-aurora-2 {
    background: conic-gradient(from 120deg,
        transparent 0deg,
        var(--netra-aura2, rgba(160,90,255,0.11)) 60deg,
        transparent 140deg,
        var(--netra-aura1, rgba(64,200,255,0.10)) 220deg,
        transparent 300deg);
    animation: netra-aurora-spin 140s linear infinite reverse;
}
@keyframes netra-aurora-spin {
    from { transform: rotate(0deg); }
    to   { transform: rotate(360deg); }
}

/* reflective floor sheen under the blob */
.netra-stage-floor {
    position: absolute;
    left: 50%; bottom: 6%;
    width: 74vmin; height: 12vmin;
    transform: translateX(-50%);
    background: radial-gradient(50% 100% at 50% 0%, var(--netra-glow-soft, rgba(139,61,240,0.16)) 0%, transparent 75%);
    filter: blur(14px);
    opacity: calc(0.5 + var(--netra-amp, 0) * 0.5);
    pointer-events: none;
}

/* orbit layer: prism rings + ripple host, centred behind the blob */
.netra-stage-orbit {
    position: absolute;
    top: 50%; left: 50%;
    width: 0; height: 0;
    pointer-events: none;
    z-index: 0;
}
.netra-stage-ring {
    position: absolute;
    width: min(74vmin, 540px); height: min(74vmin, 540px);
    top: 50%; left: 50%;
    transform: translate(-50%, -50%);
    border-radius: 50%;
    /* conic prism band, masked to a thin ring */
    background: conic-gradient(from 0deg,
        var(--netra-aura1, rgba(64,200,255,0.5)),
        var(--eye-glow, rgba(139,61,240,0.6)),
        var(--netra-aura2, rgba(160,90,255,0.5)),
        var(--eye-glow, rgba(139,61,240,0.6)),
        var(--netra-aura1, rgba(64,200,255,0.5)));
    -webkit-mask: radial-gradient(closest-side, transparent 96.5%, #000 97.5%, #000 100%);
    mask: radial-gradient(closest-side, transparent 96.5%, #000 97.5%, #000 100%);
    opacity: calc(0.28 + var(--netra-amp, 0) * 0.6);
    animation: netra-ring-spin 26s linear infinite;
    filter: blur(0.4px);
}
.netra-stage-ring-2 {
    width: min(86vmin, 640px); height: min(86vmin, 640px);
    -webkit-mask: radial-gradient(closest-side, transparent 98%, #000 99%, #000 100%);
    mask: radial-gradient(closest-side, transparent 98%, #000 99%, #000 100%);
    opacity: calc(0.14 + var(--netra-amp, 0) * 0.4);
    animation: netra-ring-spin 44s linear infinite reverse;
}
@keyframes netra-ring-spin {
    from { transform: translate(-50%, -50%) rotate(0deg); }
    to   { transform: translate(-50%, -50%) rotate(360deg); }
}
/* rings tighten and spin faster while she speaks */
.netra-stage-speaking .netra-stage-ring   { animation-duration: 9s; }
.netra-stage-speaking .netra-stage-ring-2 { animation-duration: 16s; }
.netra-stage-thinking .netra-stage-ring   { animation-duration: 5s; opacity: 0.5; }

/* word-onset ripples (spawned from client.js) */
.netra-stage-ripples { position: absolute; top: 0; left: 0; }
.netra-ripple {
    position: absolute;
    width: min(58vmin, 420px); height: min(58vmin, 420px);
    top: 50%; left: 50%;
    border-radius: 50%;
    border: 1.5px solid var(--eye-glow, rgba(139,61,240,0.6));
    box-shadow: 0 0 24px var(--netra-glow-soft, rgba(139,61,240,0.25)),
                inset 0 0 18px var(--netra-glow-soft, rgba(139,61,240,0.2));
    transform: translate(-50%, -50%) scale(0.86);
    animation: netra-ripple-out 1.5s cubic-bezier(0.16, 0.84, 0.44, 1) forwards;
    pointer-events: none;
}
@keyframes netra-ripple-out {
    0%   { transform: translate(-50%, -50%) scale(0.86); opacity: 0.9; }
    100% { transform: translate(-50%, -50%) scale(1.65); opacity: 0;   }
}

.netra-stage-head {
    position: absolute;
    top: 22px; left: 0; right: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
    z-index: 2;
}
.netra-stage-brand {
    font-size: 17px;
    font-weight: 600;
    letter-spacing: 0.08em;
    background: linear-gradient(90deg, #efe7ff, var(--iris-bright, #7fffb0));
    -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
    filter: drop-shadow(0 0 12px var(--netra-glow-soft, rgba(139,61,240,0.25)));
}
.netra-stage-pill {
    font-family: 'JetBrains Mono', monospace;
    font-size: 9px; font-weight: 700; letter-spacing: 0.18em;
    color: #ffd7a0;
    border: 1px solid rgba(255,184,77,0.4);
    background: rgba(255,184,77,0.10);
    border-radius: 999px; padding: 2px 9px;
}
/* R8.1 - live state pill rides the prism hue */
.netra-stage-pill-state {
    color: var(--iris-bright, #d8c8ff);
    border-color: var(--netra-glow-soft, rgba(216,200,255,0.35));
    background: rgba(255,255,255,0.04);
    text-transform: uppercase;
    transition: color 0.4s ease, border-color 0.4s ease;
}

.netra-stage-center {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 30px;
    z-index: 1;
    width: 100%;
    padding: 0 24px;
}

.netra-stage-blob-wrap {
    appearance: none;
    background: none;
    border: none;
    cursor: pointer;
    width: min(58vmin, 420px);
    height: min(58vmin, 420px);
    padding: 0;
    display: block;
    position: relative;
    z-index: 1;
    /* R8.1 - hue under-glow (the amp-scaled second layer is applied from
       the template <style> tag - compiler-safe there) */
    filter: drop-shadow(0 18px 60px var(--eye-glow, rgba(139,61,240,0.45)));
    transition: transform 0.3s ease;
}
.netra-stage-blob-wrap:active { transform: scale(0.97); }
/* R9.1 - kill the square focus rectangle when the blob is clicked/tapped.
   Keyboard users still get a soft glow ring via :focus-visible below. */
.netra-stage-blob-wrap,
.netra-stage-blob-wrap:hover,
.netra-stage-blob-wrap:active,
.netra-stage-blob-wrap:focus,
.netra-stage-blob-wrap:focus-within {
    outline: none !important;
    box-shadow: none;
    -webkit-tap-highlight-color: transparent;
}
.netra-stage-blob-wrap:focus-visible {
    outline: none !important;
    filter: drop-shadow(0 18px 60px var(--eye-glow, rgba(139,61,240,0.45)))
            drop-shadow(0 0 26px var(--iris-bright, rgba(216,200,255,0.8)));
}
.netra-stage-svg { width: 100%; height: 100%; overflow: visible; }

/* the big blob - warm plasma clay, Netra palette.
 * A state-tinted radial gradient is defined per stage state below; the
 * blob morphs colour as Netra listens (green), thinks (amber) and
 * speaks (violet) - live assistants shift tone, so does she. */
.netra-stage-blob-outer {
    fill: url(#netra-stage-grad);
    filter: drop-shadow(0 0 22px var(--netra-glow-soft, rgba(127,255,176,0.35)));
    transition: filter 0.5s ease;
}
.netra-stage-blob-inner {
    fill: url(#netra-blob-inner-gradient);
    mix-blend-mode: screen;
    opacity: 0.9;
}
/* R8.1 - the blob's gradient stops are written live by the prism
 * engine (idle emerald, capture cyan, thinking magenta churn,
 * speaking voice-modulated violet) - no static state palettes. */
.netra-stage .nsg-0 { stop-color: var(--nsg-0, #eafff2); }
.netra-stage .nsg-1 { stop-color: var(--nsg-1, #7fffb0); }
.netra-stage .nsg-2 { stop-color: var(--nsg-2, #2eb858); }
.netra-stage .nsg-3 { stop-color: var(--nsg-3, #063d1f); }
/* speaking blob bloom + dormant desaturation live in the template <style>
   tag (calc*var drop-shadow and grayscale(number) break the SCSS fork) */
.nsg-0, .nsg-1, .nsg-2, .nsg-3 { transition: stop-color 0.2s linear; }

.netra-stage-status {
    font-size: 17px;
    font-weight: 500;
    letter-spacing: 0.01em;
    color: #cdbff0;
    text-align: center;
    min-height: 24px;
    animation: netra-status-fade 0.4s ease;
    /* R8.1 - quiet glass chip so the status floats over the aurora */
    padding: 8px 22px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.045);
    border: 1px solid var(--netra-glow-soft, rgba(216, 200, 255, 0.14));
    -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px);
    transition: border-color 0.5s ease;
}
@keyframes netra-status-fade { from { opacity: 0; } to { opacity: 1; } }

.netra-stage-caption {
    font-size: 15px;
    color: #8f83b5;
    text-align: center;
    max-width: 640px;
    line-height: 1.5;
    min-height: 22px;
    font-style: italic;
    animation: netra-status-fade 0.3s ease;
}
/* R8.1 - Netra's own words while she speaks: brighter, hue-kissed */
.netra-stage-caption-netra {
    font-style: normal;
    font-size: 16px;
    color: #ded2ff;
    text-shadow: 0 0 22px var(--netra-glow-soft, rgba(139, 61, 240, 0.3));
}

.netra-stage-controls {
    display: flex;
    gap: 22px;
    align-items: center;
    justify-content: center;
    padding-bottom: 46px;
    z-index: 2;
}
.netra-ctl {
    width: 62px; height: 62px;
    border-radius: 50%;
    border: 1px solid rgba(216,200,255,0.25);
    background: rgba(255,255,255,0.06);
    color: #efe7ff;
    display: flex; align-items: center; justify-content: center;
    cursor: pointer;
    transition: transform 0.14s ease, background 0.18s ease, border-color 0.18s ease;
    -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px);
}
.netra-ctl:hover { transform: translateY(-2px); background: rgba(255,255,255,0.12); border-color: var(--eye-glow, rgba(216,200,255,0.5)); box-shadow: 0 4px 24px var(--netra-glow-soft, rgba(139,61,240,0.25)); }
.netra-ctl-muted { background: rgba(255,90,90,0.16); border-color: rgba(255,120,120,0.5); color: #ffb3b3; }
.netra-ctl-end { background: rgba(255,90,90,0.10); border-color: rgba(255,120,120,0.35); }
.netra-ctl-end:hover { background: rgba(255,90,90,0.22); }

/* ============================================================
 *  R8.1 - NETRA LAB (diagnostics console on the Live stage)
 * ============================================================ */
.netra-ctl-lab-on {
    background: var(--netra-glow-soft, rgba(139,61,240,0.25));
    border-color: var(--eye-glow, rgba(216,200,255,0.6));
    color: var(--iris-bright, #d8c8ff);
}
/* R8.2 - the .netra-lab window frame (position:fixed glass slab) and its
   entrance keyframes live in a literal <style> tag inside template.html:
   ServiceNow's SCSS compiler silently ate this block (backdrop-filter +
   saturate + calc/var combos), which is why the Lab rendered unstyled.
   Only compiler-safe inner styles remain here. */
.netra-lab::-webkit-scrollbar { width: 8px; }
.netra-lab::-webkit-scrollbar-thumb { background: rgba(139,61,240,0.35); border-radius: 4px; }
.netra-lab-head {
    position: sticky;
    top: 0;
    display: flex;
    align-items: baseline;
    gap: 10px;
    padding: 14px 0 10px;
    background: linear-gradient(180deg, rgba(16,12,26,0.98) 70%, rgba(16,12,26,0));
    z-index: 1;
    cursor: move;   /* drag the window from its title bar */
    user-select: none;
}
.netra-lab-grip { color: #6f6790; font-size: 11px; letter-spacing: -2px; cursor: move; }
.netra-lab-title {
    font-size: 13px;
    font-weight: 800;
    letter-spacing: 0.18em;
    background: linear-gradient(90deg, var(--iris-bright, #d8c8ff), #ffffff);
    -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.netra-lab-sub { flex: 1; font-size: 9px; letter-spacing: 0.12em; color: #8f83b5; }
.netra-lab-x {
    background: none; border: none; color: #b4a9d6;
    font-size: 18px; line-height: 1; cursor: pointer; padding: 0 2px;
}
.netra-lab-x:hover { color: #ffffff; }
.netra-lab-sec {
    border: 1px solid rgba(216, 200, 255, 0.10);
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.028);
    padding: 10px 12px 12px;
    margin-bottom: 10px;
}
.netra-lab-sec-title {
    display: flex; align-items: center; gap: 6px; flex-wrap: wrap;
    font-size: 9.5px; font-weight: 700; letter-spacing: 0.14em;
    color: var(--iris-bright, #b9a8ee);
    margin-bottom: 8px;
}
.netra-lab-chip {
    font-size: 8.5px; font-weight: 700; letter-spacing: 0.06em;
    border: 1px solid rgba(216,200,255,0.22);
    background: rgba(255,255,255,0.05);
    color: #cdbff0;
    border-radius: 999px; padding: 1px 7px;
}
.netra-lab-chip.ok  { color: #7dffb8; border-color: rgba(64,230,160,0.5); }
.netra-lab-chip.bad { color: #ff9d8f; border-color: rgba(255,110,90,0.55); }
.netra-lab-scope {
    display: block;
    width: 100%;
    height: 72px;
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.45);
    border: 1px solid rgba(216, 200, 255, 0.08);
}
.netra-lab-row { margin-top: 8px; }
.netra-lab-btns { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; }
.netra-lab-btns button {
    background: rgba(139, 61, 240, 0.16);
    border: 1px solid var(--netra-glow-soft, rgba(139, 61, 240, 0.4));
    color: #e4dbff;
    font-family: inherit;
    font-size: 10px;
    border-radius: 6px;
    padding: 5px 10px;
    cursor: pointer;
    transition: background 0.15s ease, border-color 0.15s ease;
}
.netra-lab-btns button:hover { background: rgba(139, 61, 240, 0.32); border-color: var(--eye-glow, rgba(198,96,255,0.7)); }
.netra-lab-btns button[disabled] { opacity: 0.45; cursor: default; background: rgba(139, 61, 240, 0.16); }
.netra-lab-btns em { color: #9fe8c0; font-style: normal; font-size: 10px; }
.netra-lab-calib-sentence {
    font-size: 11.5px;
    line-height: 1.5;
    color: #f0eafc;
    background: rgba(139, 61, 240, 0.10);
    border-left: 2px solid var(--iris-mid, #8b3df0);
    border-radius: 0 8px 8px 0;
    padding: 7px 10px;
}
.netra-lab-kv { display: flex; gap: 8px; margin-top: 6px; }
.netra-lab-kv span { flex: none; width: 52px; color: #8f83b5; font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; padding-top: 1px; }
.netra-lab-kv em { font-style: normal; color: #d9d0f0; line-height: 1.45; }
.netra-lab-grid {
    display: flex;
    flex-wrap: wrap;
}
.netra-lab-grid > div {
    display: flex;
    justify-content: space-between;
    width: 50%;
    box-sizing: border-box;
    padding: 2px 10px 2px 0;
}
.netra-lab-grid span { color: #8f83b5; }
.netra-lab-grid b { color: #eae4f8; font-weight: 600; }
.netra-lab-grid b.bad  { color: #ff9d8f; }
.netra-lab-grid b.warn { color: #ffd34d; }
.netra-lab-hue-row { display: flex; align-items: center; gap: 8px; }
/* R11 - background feed: the live event log inside the Lab window */
.netra-lab-feed {
    max-height: 180px;
    overflow-y: auto;
    background: rgba(10, 7, 18, 0.55);
    border: 1px solid rgba(139, 61, 240, 0.22);
    border-radius: 8px;
    padding: 6px 8px;
    font-size: 10px;
    line-height: 1.5;
}
.netra-lab-feed-row { display: flex; gap: 7px; align-items: baseline; }
.netra-lab-feed-t { color: #6f6494; flex: none; font-size: 9px; }
.netra-lab-feed-k { flex: none; width: 40px; text-transform: uppercase; letter-spacing: 0.06em; font-size: 8.5px; color: #a89cc8; }
.netra-lab-feed-m { color: #d9d0f0; word-break: break-word; }
.netra-lab-feed-k.lk-err   { color: #ff7676; }
.netra-lab-feed-k.lk-warn  { color: #ffd34d; }
.netra-lab-feed-k.lk-mem   { color: #7dffb8; }
.netra-lab-feed-k.lk-srv   { color: #d96570; }
.netra-lab-feed-k.lk-tts   { color: #4dd0e1; }
.netra-lab-feed-k.lk-dev   { color: #8ab4f8; }
.netra-lab-feed-k.lk-lab   { color: #c39bd3; }
.netra-lab-feed-k.lk-rec   { color: #81c995; }
.netra-lab-feed-k.lk-mic   { color: #f9ab00; }
.netra-lab-feed-k.lk-wake  { color: #34a853; }
.netra-lab-feed-k.lk-barge { color: #ff8fab; }
.netra-lab-feed-k.lk-nav   { color: #80cbc4; }
.netra-lab-feed-k.lk-nlp   { color: #b39ddb; }
/* R9 - Lab preference controls */
.netra-lab-slider { display: flex; align-items: center; gap: 8px; }
.netra-lab-slider label { color: #8f83b5; font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; flex: none; }
.netra-lab-slider input { flex: 1; accent-color: #8b3df0; }
.netra-lab-slider em { font-style: normal; color: #eae4f8; width: 34px; text-align: right; }
.netra-lab-selects { display: flex; align-items: center; gap: 8px; }
.netra-lab-selects label { color: #8f83b5; font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; width: 70px; flex: none; }
.netra-lab-selects select {
    flex: 1;
    background: #14101f;
    color: #e4dbff;
    border: 1px solid rgba(139, 61, 240, 0.35);
    border-radius: 6px;
    font-family: inherit;
    font-size: 10.5px;
    padding: 4px 6px;
}
.netra-lab-check { display: inline-flex; align-items: center; gap: 5px; color: #cdbff0; font-size: 10px; cursor: pointer; }
.netra-lab-check input { accent-color: #8b3df0; }
.netra-lab-cmd { display: flex; gap: 8px; }
.netra-lab-cmd input {
    flex: 1;
    background: #14101f;
    color: #f0eafc;
    border: 1px solid rgba(139, 61, 240, 0.35);
    border-radius: 6px;
    font-family: inherit;
    font-size: 11px;
    padding: 6px 8px;
}
.netra-lab-cmd input:focus { outline: none; border-color: rgba(198, 96, 255, 0.7); }
.netra-lab-cmd button {
    background: rgba(139, 61, 240, 0.16);
    border: 1px solid rgba(139, 61, 240, 0.4);
    color: #e4dbff;
    font-family: inherit;
    font-size: 10px;
    border-radius: 6px;
    padding: 5px 12px;
    cursor: pointer;
}
.netra-lab-cmd button[disabled] { opacity: 0.45; cursor: default; }
.netra-lab-swatch {
    width: 22px; height: 22px;
    border-radius: 50%;
    background: radial-gradient(circle at 35% 30%, var(--iris-bright, #aef0d0), var(--iris-mid, #2eb858) 60%, var(--iris-deep, #021a0d));
    box-shadow: 0 0 12px var(--eye-glow, rgba(127,255,176,0.55));
    border: 1px solid rgba(255,255,255,0.25);
}

@media (max-width: 480px) {
    .netra-stage-blob-wrap { width: 72vmin; height: 72vmin; }
    .netra-stage-status { font-size: 15px; }
    .netra-stage-controls { padding-bottom: 34px; }
    .netra-lab { top: 56px; right: 10px; width: calc(100vw - 20px); max-height: calc(100vh - 70px); }
}

sp_widget.script:
/**
 * Netra Mic widget - SERVER SCRIPT (R9)
 *
 * this is the back half of Netra: one big action router + the Gemini
 * function-calling loop + ~85 tools. the model decides when to call a
 * tool (create ticket, list, resolve, describe the form, whatever) and
 * we run it thru GlideRecord / the Netra script includes, then loop the
 * result back for a natural spoken reply.
 *
 * headline stuff thats in here now:
 *   - FULL ticket control on every ticket type (writes on by default,
 *     ticket_writes=false is the emergency kill-switch)
 *   - form intelligence: mandatory fields, buttons + what they do,
 *     field-change effects, pre-submit checks, flows, approvals,
 *     related records, my_recent_records
 *   - reminders, prosody-aware sentiment, short-form ticket numbers,
 *     the analyst/developer lexicon that seeds the recogniser
 *   - one gotcha to remeber: this whole file is a single IIFE and the
 *     router at the top runs first, so data tables MUST be hoisted
 *     functions, never plain vars (learned that one the hard way)
 *
 * Setup:
 *   System Property  x_196061_netra_v1.gemini_api_key   = <your key>
 *   System Property  x_196061_netra_v1.gemini_model     = gemini-2.5-flash  (optional)
 *
 *   Get a free Gemini API key at https://aistudio.google.com/apikey
 *
 * Protocol:
 *   input.action == 'chat'      -> input.message, input.history -> data.response
 *   input.action == 'poll'      -> data.notifications
 *   input.action == 'reset'     -> clears server-side memory (history is client-side)
 *   (initial load)              -> data.user_name, data.paused, data.has_api_key
 */
(function () {

    var SCOPE = 'x_196061_netra_v1';
    var user  = gs.getUserID();

    var action = (input && input.action) ? String(input.action) : null;

    // ---- Always-on state (cheap: needed by every action incl. the 9s poll) ----
    data.user_name   = gs.getUserDisplayName();
    data.user_sys_id = user;
    data.error       = null;
    data.has_api_key = !!gs.getProperty(SCOPE + '.gemini_api_key');

    // R4.7 - PERF: one query both ensures a pref row exists AND reads pause
    // state, replacing the previous two back-to-back GlideRecord queries on
    // the same _user_pref row. Runs on every action because poll needs pause.
    _ensurePrefAndPause();

    // R4.7 - PERF: vocab (5 GlideRecord queries, ~80ms) and the training blob
    // are consumed by the client ONLY at boot, to build the speech recognizer.
    // They were previously rebuilt on EVERY server call - including the
    // 9-second notification poll - so an idle widget ran ~6 needless queries
    // and shipped a fat vocab/training payload back every 9s, forever. Build
    // them only on the initial widget load (action === null). The client keeps
    // its boot snapshot, so poll/chat turns no longer need them re-sent.
    // R2.3 - per-user voice training (vocab + aliases) lives in the Netra
    // Context row; expose it so the client can rebuild personal recognizer
    // hints from server truth.
    if (!action) {
        data.vocab = _getVocab();
        try {
            var trainSnap = _trainingRead();
            data.training = {
                vocab:   trainSnap.vocab   || {},
                aliases: trainSnap.aliases || {}
            };
        } catch (eT) { data.training = { vocab: {}, aliases: {} }; }
    }

    if (action === 'chat') {
        try {
            // R4.5 - cap the user message. The history-byte cap below only
            // trims old turns; the CURRENT message is fed raw to Gemini. A
            // hostile multi-MB payload could blow the 12s HTTP timeout
            // before any history trim runs. Release X: 8000 -> 16000 so a
            // long spoken dictation never gets cut mid-thought.
            var _userMsg = String((input && input.message) || '').trim();
            if (_userMsg.length > 16000) _userMsg = _userMsg.substring(0, 16000);
            // image_b64 cap - 4 MB base64 ~ 3 MB binary, plenty for a screen
            if (input && typeof input.image_b64 === 'string' && input.image_b64.length > 4000000) {
                input.image_b64 = input.image_b64.substring(0, 4000000);
            }
            data.response = _chat(
                _userMsg,
                (input && Array.isArray(input.history)) ? input.history : [],
                !!(input && input.live_mode),
                (input && input.prosody) || null
            );
        } catch (e) {
            gs.error('[NetraGemini] chat outer error: ' + e);
            data.response = { ok: false, message: 'Sorry, I hit a server error: ' + String(e.message || e) };
        }
    } else if (action === 'poll') {
        try {
            if (data.paused) {
                data.notifications = [];
            } else {
                var gr = new GlideRecord(SCOPE + '_notification');
                gr.addQuery('user', user);
                gr.addQuery('delivered', false);
                gr.orderBy('sys_created_on');
                gr.setLimit(10);
                gr.query();
                var out = [];
                while (gr.next()) {
                    out.push({
                        id: String(gr.sys_id),
                        message: String(gr.message),
                        kind: String(gr.kind),
                        ticket_number: String(gr.ticket_number)
                    });
                    gr.delivered = true;
                    gr.delivered_at = new GlideDateTime();
                    gr.update();
                }
                data.notifications = out;
            }
        } catch (eP) {
            gs.error('[NetraGemini] poll: ' + eP);
            data.notifications = [];
        }
    } else if (action === 'save_training') {
        // R2.3 - client sends its current vocab + aliases blob; we persist it
        try {
            var v = (input && input.vocab)   ? input.vocab   : null;
            var a = (input && input.aliases) ? input.aliases : null;
            if (!v && !a) {
                data.training_result = { ok: false, error: 'Neither vocab nor aliases provided.' };
            } else {
                _trainingWrite(v, a);
                var saved = _trainingRead();
                data.training_result = {
                    ok: true,
                    vocab_count:   Object.keys(saved.vocab).length,
                    aliases_count: Object.keys(saved.aliases).length,
                    message: 'Training saved to ServiceNow.'
                };
            }
        } catch (eTS) {
            data.training_result = { ok: false, error: String(eTS.message || eTS) };
        }
    } else if (action === 'clear_training') {
        try {
            _trainingWrite({}, {});
            data.training_result = { ok: true, message: 'Training cleared.' };
        } catch (eC) {
            data.training_result = { ok: false, error: String(eC.message || eC) };
        }
    } else if (action === 'gemini_tts') {
        // R2.8 - synthesise the given text via Gemini's native TTS model
        // (gemini-2.5-flash-preview-tts). Same Gemini API key, no extra
        // service. Returns base64 PCM 24kHz mono which the client wraps
        // in a WAV header and plays. Falls back gracefully if the model
        // is unavailable - client retries via Edge TTS.
        try {
            var text  = String((input && input.text)  || '').substring(0, 4000);
            var voice = String((input && input.voice) || 'Kore');
            if (!text) {
                data.gemini_tts = { ok: false, error: 'no text' };
            } else {
                var key = gs.getProperty(SCOPE + '.gemini_api_key');
                if (!key) {
                    data.gemini_tts = { ok: false, error: 'no api key' };
                } else {
                    var url = 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash-preview-tts:generateContent?key=' + encodeURIComponent(key);
                    var body = {
                        contents: [{ parts: [{ text: text }] }],
                        generationConfig: {
                            responseModalities: ['AUDIO'],
                            speechConfig: {
                                voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } }
                            }
                        }
                    };
                    var rm = new sn_ws.RESTMessageV2();
                    rm.setEndpoint(url);
                    rm.setHttpMethod('POST');
                    rm.setRequestHeader('Content-Type', 'application/json');
                    rm.setRequestBody(JSON.stringify(body));
                    rm.setHttpTimeout(15000);
                    var r = rm.execute();
                    var code = r.getStatusCode();
                    if (code !== 200) {
                        data.gemini_tts = { ok: false, error: 'HTTP ' + code, body: String(r.getBody() || '').substring(0, 200) };
                    } else {
                        var parsed = JSON.parse(r.getBody() || '{}');
                        var part = parsed && parsed.candidates && parsed.candidates[0] &&
                                   parsed.candidates[0].content && parsed.candidates[0].content.parts &&
                                   parsed.candidates[0].content.parts[0];
                        if (part && part.inlineData && part.inlineData.data) {
                            data.gemini_tts = {
                                ok: true,
                                mime: String(part.inlineData.mimeType || 'audio/L16;rate=24000'),
                                b64:  String(part.inlineData.data),
                                voice: voice
                            };
                        } else {
                            data.gemini_tts = { ok: false, error: 'no audio in response' };
                        }
                    }
                }
            }
        } catch (eG) {
            data.gemini_tts = { ok: false, error: String(eG.message || eG) };
        }
    } else if (action === 'rewind_mem') {
        // R2.10 - conversational repair: pop the last conversation exchange from
        // the unified Context blob. Client also drops the last 2 entries from
        // geminiHistory so the next chat call starts clean.
        try {
            var blob = _ctxReadBlob();
            var rewinded = false;
            if (blob.mem && blob.mem.length) {
                blob.mem.pop();
                _ctxWriteBlob(blob);
                rewinded = true;
            }
            data.rewind_result = { ok: true, popped: rewinded, mem_length: (blob.mem || []).length };
        } catch (eR) {
            data.rewind_result = { ok: false, error: String(eR.message || eR) };
        }
    } else if (action === 'debug') {
        try {
            var key = gs.getProperty(SCOPE + '.gemini_api_key') || '';
            var mdl = gs.getProperty(SCOPE + '.gemini_model', 'gemini-flash-lite-latest');
            var toolDecls = _toolDeclarations();
            var toolNames = [];
            if (toolDecls[0] && toolDecls[0].functionDeclarations) {
                for (var ti = 0; ti < toolDecls[0].functionDeclarations.length; ti++) {
                    toolNames.push(toolDecls[0].functionDeclarations[ti].name);
                }
            }
            data.debug = {
                version: 'v7.0',
                scope: SCOPE,
                user_name: gs.getUserDisplayName(),
                user_sys_id: user,
                model: mdl,
                api_key_status: key ? ('set (length=' + key.length + ', prefix=' + key.substring(0, 6) + ')') : 'MISSING',
                tool_count: toolNames.length,
                tools: toolNames,
                paused: !!data.paused,
                paused_until: data.paused_until || '',
                server_time: String(new GlideDateTime())
            };
        } catch (eD) {
            data.debug = { error: String(eD.message || eD) };
        }
    }

    /* ===================================================================
     *  Gemini chat with tool use
     * =================================================================== */
    function _chat(userMessage, history, liveMode, prosody) {
        if (!userMessage) {
            return { ok: false, message: 'I did not catch that. Kindly say it again.' };
        }
        // R8.2 - voice-delivery metadata rides the turn as a bracketed tag
        // the model reads but never speaks (prompt explains the format).
        if (prosody && (prosody.wpm || prosody.level)) {
            userMessage += ' [voice delivery: ' +
                (prosody.wpm ? ('~' + prosody.wpm + ' wpm') : '') +
                (prosody.level ? (', loudness ' + prosody.level + '/100') : '') +
                (prosody.variance ? (', dynamics ' + prosody.variance) : '') + ']';
        }
        var apiKey = gs.getProperty(SCOPE + '.gemini_api_key');
        if (!apiKey) {
            return {
                ok: false,
                message: 'My AI key has not been configured yet. Kindly set the system property ' +
                         SCOPE + '.gemini_api_key with your Gemini API key from Google AI Studio.'
            };
        }
        // R4.7 - PERF: default to gemini-flash-lite-latest (~1.0s) instead of
        // gemini-2.5-flash (~2-4s with thinking-token overhead). The tool-use
        // loop can fire this model up to 5 times per turn, so the primary model
        // choice dominates perceived latency. flash-lite handles Netra's tool
        // calls well and was already the first fallback the chain relied on;
        // making it the *primary* removes 1-3s from every voice turn. Override
        // via the x_196061_netra_v1.gemini_model property if richer reasoning
        // is needed on a given instance.
        var model = gs.getProperty(SCOPE + '.gemini_model', 'gemini-flash-lite-latest');
        // R7 - AUTO-ROUTED BRAINS. Simple commands stay on flash-lite
        // (~1s); turns that smell like reasoning (long, multi-question,
        // analytical verbs, multi-step) escalate to gemini-2.5-flash for
        // a smarter answer at +1-2s. Only applies when the property is
        // still the default - an explicit gemini_model pins every turn.
        var routeReason = 'fast';
        if (model === 'gemini-flash-lite-latest') {
            if (_isComplexTurn(userMessage)) { model = 'gemini-2.5-flash'; routeReason = 'complex'; }
        } else {
            routeReason = 'pinned';
        }

        // Build conversation history for Gemini.
        // R11 - DEEP MEMORY. The old cap kept the last 40 raw ENTRIES, but
        // tool-heavy turns burn 2-4 entries each, so a dozen exchanges could
        // shove the user's actual prompts clean out of the window - memory
        // felt like it exhausted way too quickly. New envelope:
        //   - Window is counted in USER PROMPTS: walk backwards and keep
        //     everything needed to cover the last 50 things the user said
        //     (hard safety ceiling of 400 entries)
        //   - Truncate tool-response bodies over 4000 chars to a digest
        //   - Strip any inlineData (screenshot frames) from past turns
        //   - Hard byte cap: if still over 300KB, drop oldest turns
        //   - Anything dropped leaves a one-line-per-prompt digest behind
        //     (injected as a synthetic first exchange) so she still "knows"
        //     what was said even past the window - no more amnesia cliffs
        var MEM_PROMPT_WINDOW = 50;
        var MEM_ENTRY_CEILING = 400;
        var MEM_BYTE_CAP = 300000;
        var droppedPrompts = [];   // digest lines for turns that fall off
        function _isUserPrompt(entry) {
            if (!entry || entry.role !== 'user' || !entry.parts) return false;
            for (var q = 0; q < entry.parts.length; q++) {
                var pt = entry.parts[q];
                if (pt && pt.text && !pt.functionResponse) return true;
            }
            return false;
        }
        function _promptLine(entry) {
            for (var q = 0; q < entry.parts.length; q++) {
                var pt = entry.parts[q];
                if (pt && pt.text) return String(pt.text).replace(/\s+/g, ' ').substring(0, 140);
            }
            return '';
        }
        var contents = [];
        if (Array.isArray(history)) {
            // walk backwards until 50 user prompts are inside the window
            var start = history.length, promptsSeen = 0;
            while (start > 0 && (history.length - start) < MEM_ENTRY_CEILING) {
                var cand = history[start - 1];
                if (_isUserPrompt(cand)) {
                    if (promptsSeen >= MEM_PROMPT_WINDOW) break;
                    promptsSeen++;
                }
                start--;
            }
            // whatever fell off the front still leaves a memory line behind
            for (var d = 0; d < start; d++) {
                if (_isUserPrompt(history[d])) droppedPrompts.push(_promptLine(history[d]));
            }
            for (var i = start; i < history.length; i++) {
                var h = history[i];
                if (!h || !h.role || !h.parts) continue;
                var sanitisedParts = [];
                for (var p = 0; p < h.parts.length; p++) {
                    var part = h.parts[p];
                    if (!part) continue;
                    // Drop inlineData (binary frames) from past turns
                    if (part.inlineData) continue;
                    if (part.functionResponse && part.functionResponse.response) {
                        // Truncate large tool-result bodies in-place
                        var resp = part.functionResponse.response;
                        var s = '';
                        try { s = JSON.stringify(resp); } catch (eS) {}
                        if (s.length > 4000) {
                            sanitisedParts.push({
                                functionResponse: {
                                    name: part.functionResponse.name,
                                    response: { result: { ok: true, _truncated: true, summary: s.substring(0, 2000) + '...[' + (s.length - 2000) + ' more chars trimmed]' } }
                                }
                            });
                        } else {
                            sanitisedParts.push(part);
                        }
                    } else if (part.text && part.text.length > 6000) {
                        sanitisedParts.push({ text: part.text.substring(0, 6000) + '...[truncated]' });
                    } else {
                        sanitisedParts.push(part);
                    }
                }
                if (sanitisedParts.length) {
                    contents.push({ role: h.role, parts: sanitisedParts });
                }
            }
            // Hard byte cap. R4.7 - PERF: compute the total size once and
            // subtract each dropped turn's own length, instead of
            // re-serialising the entire contents array on every iteration
            // (previously O(n^2) on long sessions).
            var size = JSON.stringify(contents).length;
            while (contents.length > 2 && size > MEM_BYTE_CAP) {
                var dropped = contents.shift();
                if (_isUserPrompt(dropped)) droppedPrompts.push(_promptLine(dropped));
                size -= JSON.stringify(dropped).length + 1;   // +1 ~ comma separator
            }
            if (size > MEM_BYTE_CAP) {
                gs.warn('[NetraGemini] history still ' + size + ' bytes after pruning; will rely on Gemini to handle');
            }
        }
        // R11 - stitch the dropped prompts back in as a compact digest, so
        // "what was the first thing I asked you?" keeps working even after
        // the live window has rolled past it.
        if (droppedPrompts.length) {
            var digestLines = droppedPrompts.slice(-MEM_PROMPT_WINDOW);
            contents.unshift(
                { role: 'user',  parts: [{ text: '[memory digest - things I said earlier in this conversation, oldest first]\n- ' + digestLines.join('\n- ') }] },
                { role: 'model', parts: [{ text: 'Noted. I remember everything you said earlier and will use it as context.' }] }
            );
        }
        // R1.4 - vision support: if the client attached an image, send it
        // as inlineData alongside the text. Gemini 2.5-flash is multimodal.
        var userParts = [{ text: userMessage }];
        if (input && input.image_b64) {
            userParts.unshift({
                inlineData: {
                    mimeType: input.image_mime || 'image/png',
                    data:     String(input.image_b64)
                }
            });
        }
        contents.push({ role: 'user', parts: userParts });

        var systemInstruction = _systemPrompt(liveMode);
        var tools = _toolDeclarations(liveMode);

        // Tool-use loop (max 8 iterations to prevent runaway; Release X
        // raised from 5 so multi-step research turns don't bail early)
        var modelUsed = null;
        var toolsCalled = [];   // R1 - track which tools were invoked
        var clientDirectives = {};   // R2 - navigate_url, click_button_label, etc.
        var shrunkOnce = false;   // R11 - one in-place history shrink before giving up
        for (var iter = 0; iter < 8; iter++) {
            var resp = _callGemini(apiKey, model, contents, tools, systemInstruction);
            if (resp._model_used) modelUsed = resp._model_used;
            if (resp.error) {
                gs.error('[NetraGemini] API error: ' + resp.error);
                var friendly = 'Sorry, the AI service is busy right now. Kindly try again in a moment.';
                var err = String(resp.error);
                if (err.indexOf('429') >= 0)        friendly = 'I have hit the rate limit. Kindly wait a minute and try again.';
                else if (err.indexOf('401') >= 0 || err.indexOf('403') >= 0) friendly = 'My API key is not authorised. Kindly check the configuration.';
                else if (err.indexOf('400') >= 0) {
                    // R11 - 400 after a long session usually means payload too
                    // large. The old behaviour nuked the WHOLE memory
                    // (force_history_reset) which felt like amnesia. Now:
                    // drop the oldest half (their prompts join the digest)
                    // and retry once - only a second 400 asks for a trim,
                    // and even then the client keeps the newer half.
                    if (!shrunkOnce && contents.length > 6) {
                        shrunkOnce = true;
                        var half = Math.floor(contents.length / 2);
                        var shrunkLines = [];
                        for (var sd = 0; sd < half; sd++) {
                            if (_isUserPrompt(contents[sd])) shrunkLines.push(_promptLine(contents[sd]));
                        }
                        contents = contents.slice(half);
                        if (shrunkLines.length) {
                            contents.unshift(
                                { role: 'user',  parts: [{ text: '[memory digest - things I said earlier in this conversation]\n- ' + shrunkLines.join('\n- ') }] },
                                { role: 'model', parts: [{ text: 'Noted. I remember everything you said earlier.' }] }
                            );
                        }
                        gs.warn('[NetraGemini] 400 - shrank history to ' + contents.length + ' entries and retrying');
                        iter--;   // this attempt should not eat a tool-loop round
                        continue;
                    }
                    friendly = 'My memory got a bit too heavy, so I compressed the older half. Could you say that again?';
                    return { ok: false, message: friendly, error_detail: err, trim_history_half: true };
                }
                else if (err.indexOf('404') >= 0)   friendly = 'The AI model is not available right now.';
                else if (err.indexOf('exhausted') >= 0) friendly = 'All AI models are busy at the moment. Kindly try again in a few seconds.';
                return { ok: false, message: friendly, error_detail: err };
            }

            var candidate = (resp.candidates && resp.candidates[0]) || null;
            if (!candidate || !candidate.content || !candidate.content.parts) {
                return { ok: false, message: 'I got an empty response. Kindly try again.' };
            }

            var parts = candidate.content.parts;
            var functionCalls = [];
            var textChunks = [];
            for (var p = 0; p < parts.length; p++) {
                if (parts[p].functionCall) functionCalls.push(parts[p].functionCall);
                if (parts[p].text) textChunks.push(parts[p].text);
            }

            // If the model called a tool, execute it and loop
            if (functionCalls.length) {
                // Add the model's turn (with the function call) to contents
                contents.push({ role: 'model', parts: parts });

                // Execute each function call and append responses
                var responseParts = [];
                for (var f = 0; f < functionCalls.length; f++) {
                    var fc = functionCalls[f];
                    var result = _runTool(fc.name, fc.args || {});
                    toolsCalled.push(fc.name);   // R1 - record tool call
                    // R2 - hoist client-side directives so the AngularJS
                    // controller can act on them after the reply.
                    if (result && result.navigate_url)       clientDirectives.navigate_url       = result.navigate_url;
                    if (result && result.click_button_label) clientDirectives.click_button_label = result.click_button_label;
                    // R2.4 - open new tab directive
                    if (result && result.open_url)           clientDirectives.open_url           = result.open_url;
                    // R8.2 - local reminder scheduling directive
                    if (result && result.reminder_at_ms) {
                        clientDirectives.reminder_at_ms = result.reminder_at_ms;
                        clientDirectives.reminder_text  = result.reminder_text || 'Reminder.';
                    }
                    gs.info('[NetraGemini] tool ' + fc.name + ' -> ' + JSON.stringify(result).substring(0, 200));
                    responseParts.push({
                        functionResponse: {
                            name: fc.name,
                            response: { result: result }
                        }
                    });
                }
                contents.push({ role: 'user', parts: responseParts });
                continue;
            }

            // Final natural-language reply
            var finalText = textChunks.join(' ').trim() || 'Done.';

            // Persist last spoken utterance into the context table (best-effort)
            try {
                var ctx = new NetraContext();
                ctx.setLastUtterance(finalText);
            } catch (eC) {}

            // Re-read pause state in case a tool toggled it
            _setPauseState();

            // Append the final model turn to contents so client history is complete
            contents.push({ role: 'model', parts: [{ text: finalText }] });

            // R1.4 - persist exchange into long-term memory (capped at 40 turns)
            try { _memAppend(userMessage, finalText); } catch (eM) {}

            // R2.12 - SENTIMENT TRACKING (algorithmic, not prompt-only)
            //   Run a fast Gemini-reason classification on the user's turn,
            //   store result in Context blob, return a flag the client can
            //   surface as a proactive escalation suggestion if two
            //   consecutive frustrated turns are detected.
            var sentimentSignal = null;
            try { sentimentSignal = _trackSentiment(userMessage); } catch (eSent) {
                gs.warn('[NetraSentiment] track failed: ' + (eSent.message || eSent));
            }

            return {
                ok: true,
                message: finalText,
                history: contents,
                paused: data.paused,
                model_used: modelUsed,
                route_reason: routeReason,    // R7 - fast | complex | pinned
                tools_called: toolsCalled,    // R1 - for dev panel graph
                directives: clientDirectives, // R2 - navigate_url / click_button_label
                sentiment: sentimentSignal,   // R2.12 - {label, score, consecutive_frustrated, suggest_escalation}
                memory: {                     // R11 - deep-memory telemetry for the Lab
                    prompts: (typeof promptsSeen === 'number') ? promptsSeen : 0,
                    digested: droppedPrompts.length,
                    entries: contents.length
                }
            };
        }

        return { ok: false, message: 'I am thinking too much, kindly try again with a simpler request.' };
    }

    /* ===================================================================
     *  R2.12 - ALGORITHMIC SENTIMENT TRACKING
     *
     *  Per-turn classification (positive / neutral / frustrated) stored in
     *  the Context blob. When the rolling counter of consecutive frustrated
     *  turns hits 2, the response flags suggest_escalation=true so the
     *  client can render a "Want me to escalate?" affordance without
     *  waiting for the LLM's prompt-perception to catch it.
     * =================================================================== */
    // Fast keyword cues that warrant a real LLM classification call. We only
    // burn a Gemini call when one of these is present — otherwise the turn
    // is treated as 'neutral' with no API cost. Keeps free-tier quota usable.
    var SENTIMENT_CUES = [
        'damn', 'stupid', 'still not', 'still broken', "why isn't", "why isnt",
        'why is it not', 'why is this not', 'this is the third', 'this is the fourth',
        'i already', 'i told you', 'i said', 'are you kidding', 'come on',
        'frustrating', 'annoying', 'useless', 'ridiculous', 'urgent', '!!!',
        'urgently', 'asap', 'right now', "doesn't work", 'does not work',
        'not working', 'wrong', "won't work", 'wont work'
    ];

    function _trackSentiment(userMessage) {
        if (!userMessage || userMessage.length < 3) return null;

        // R2.12.1 - two-stage sentiment classification:
        // (1) Fast keyword + ALL-CAPS pre-filter (free, no API call)
        // (2) Gemini classifier ONLY when stage 1 flags potential frustration
        var lc = String(userMessage).toLowerCase();
        var raw = String(userMessage);
        var hasCue = false;
        for (var i = 0; i < SENTIMENT_CUES.length && !hasCue; i++) {
            if (lc.indexOf(SENTIMENT_CUES[i]) >= 0) hasCue = true;
        }
        // SHOUTING ALL CAPS for >5 chars (excluding ticket numbers, etc.)
        if (!hasCue && raw.length > 5) {
            var letters = raw.replace(/[^a-zA-Z]/g, '');
            if (letters.length > 5 && letters.toUpperCase() === letters && letters.toLowerCase() !== letters) {
                hasCue = true;
            }
        }

        // Stage 1 verdict: NEUTRAL — bypass Gemini, just bookkeeping
        if (!hasCue) {
            try {
                var b = _ctxReadBlob();
                b.sentiment = (b.sentiment && b.sentiment.history) ? b.sentiment : { history: [], consecutive_frustrated: 0 };
                b.sentiment.history.push({ t: new GlideDateTime().toString(), label: 'neutral', score: 0 });
                if (b.sentiment.history.length > 10) b.sentiment.history = b.sentiment.history.slice(-10);
                b.sentiment.consecutive_frustrated = 0;
                _ctxWriteBlob(b);
                return { label: 'neutral', score: 0, consecutive_frustrated: 0,
                         suggest_escalation: false, source: 'keyword_filter' };
            } catch (eN) { return { label: 'neutral', score: 0, error: 'persist_failed' }; }
        }

        // R4.7 - PERF: by default do NOT fire a second, blocking Gemini call on
        // the reply path. A cue word or ALL-CAPS shout is already a strong
        // frustration signal, so classify from it directly and skip the extra
        // ~1-2s LLM round-trip the user would otherwise wait through *before
        // hearing any reply*. The consecutive-frustrated escalation counter
        // still works. Set x_196061_netra_v1.sentiment_llm=true to restore the
        // LLM-refined classification when accuracy matters more than latency.
        var useLlmSentiment = gs.getProperty(SCOPE + '.sentiment_llm', 'false') === 'true';
        if (!useLlmSentiment) {
            try {
                var bk = _ctxReadBlob();
                bk.sentiment = (bk.sentiment && bk.sentiment.history) ? bk.sentiment : { history: [], consecutive_frustrated: 0 };
                bk.sentiment.history.push({ t: new GlideDateTime().toString(), label: 'frustrated', score: 0.6 });
                if (bk.sentiment.history.length > 10) bk.sentiment.history = bk.sentiment.history.slice(-10);
                bk.sentiment.consecutive_frustrated = (bk.sentiment.consecutive_frustrated || 0) + 1;
                _ctxWriteBlob(bk);
                return {
                    label: 'frustrated', score: 0.6,
                    consecutive_frustrated: bk.sentiment.consecutive_frustrated,
                    suggest_escalation: bk.sentiment.consecutive_frustrated >= 2,
                    source: 'keyword_filter'
                };
            } catch (eKw) { return { label: 'frustrated', score: 0.6, error: 'persist_failed' }; }
        }

        // Stage 2: LLM classifier (only when cues present AND opt-in enabled)
        var schema = {
            type: 'object',
            properties: {
                label: { type: 'string', enum: ['positive', 'neutral', 'frustrated'] },
                score: { type: 'number', description: '0 = calm, 1 = highly frustrated' },
                reason: { type: 'string', description: 'one short clause explaining the call' }
            },
            required: ['label', 'score']
        };
        var systemText = 'Classify the user utterance by emotional tone. Look for: sharp wording, ' +
                         'repeated requests, "this is the third time", profanity, exasperated phrasing, ' +
                         'urgency markers ("now!", "still broken"). Output JSON only.';
        var resp = _reason(systemText, 'Utterance: ' + String(userMessage).substring(0, 800), schema, 200);
        if (resp.error) return { label: 'neutral', score: 0, error: resp.error };

        var parsed = resp.json || {};
        var label  = parsed.label || 'neutral';
        var score  = typeof parsed.score === 'number' ? parsed.score : 0;

        // Persist in Context blob as a rolling list (last 10 turns)
        try {
            var blob = _ctxReadBlob();
            blob.sentiment = (blob.sentiment && blob.sentiment.history) ? blob.sentiment : { history: [], consecutive_frustrated: 0 };
            blob.sentiment.history.push({
                t: new GlideDateTime().toString(),
                label: label,
                score: score
            });
            if (blob.sentiment.history.length > 10) {
                blob.sentiment.history = blob.sentiment.history.slice(-10);
            }
            // Update the consecutive-frustrated counter
            if (label === 'frustrated') {
                blob.sentiment.consecutive_frustrated =
                    (blob.sentiment.consecutive_frustrated || 0) + 1;
            } else {
                blob.sentiment.consecutive_frustrated = 0;
            }
            _ctxWriteBlob(blob);
            return {
                label: label,
                score: score,
                reason: parsed.reason || '',
                consecutive_frustrated: blob.sentiment.consecutive_frustrated,
                suggest_escalation: blob.sentiment.consecutive_frustrated >= 2,
                source: 'llm'
            };
        } catch (eC) {
            return { label: label, score: score, error: 'persist_failed: ' + eC.message };
        }
    }

    /* ===================================================================
     *  Gemini call with model fallback chain
     *  On 503/429/UNAVAILABLE, transparently retry on a sibling model.
     *  All in Google's free tier.
     * =================================================================== */
    // R7 - complexity sniff for the model auto-router. Cheap heuristics
    // only; anything ambiguous stays on the fast model.
    function _isComplexTurn(msg) {
        var m = String(msg || '');
        if (m.length > 140) return true;
        if ((m.match(/\?/g) || []).length >= 2) return true;
        if (/\b(why|explain|analy[sz]e|summar|compare|comparison|plan|triage|brief(ing)?|recommend|suggest|should (i|we)|how (do|would|can) (i|we)|walk me|deep dive|investigate|root cause|strategy|pros and cons|trade ?offs?|what'?s the best|prioriti[sz]e|assess|evaluate)\b/i.test(m)) return true;
        if (/\b(and (then|also)|after that|first .* then)\b/i.test(m)) return true;
        return false;
    }

    function _callGemini(apiKey, requestedModel, contents, tools, systemInstruction) {
        // R2.12.5 - SPEED-FIRST chain, empirically calibrated May 2026:
        //   gemini-flash-lite-latest:  ~1.0s  <-- alias to Google's current
        //                                         best lite (3.1 / 2.5)
        //   gemini-3.1-flash-lite:     ~1.7s
        //   gemini-2.5-flash-lite:     ~3-5s  (variable, latest preview)
        //   gemini-2.5-flash:          ~2-4s  (has thinking-token overhead
        //                                     even with thinkingBudget=0)
        // Pro models dropped — too slow for an interactive voice loop.
        var chain = [requestedModel];
        // R3.6 - trimmed from 7 to 3 alternates. With 12s timeout each, the
        // old worst case was 7x12=84s (which felt like a server hang).
        // Now: 3 attempts max + 20s total deadline -> never exceeds ~22s.
        ['gemini-flash-lite-latest',
         'gemini-2.5-flash-lite',
         'gemini-2.0-flash-lite'].forEach(function (m) {
            if (chain.indexOf(m) < 0) chain.push(m);
        });

        var lastErr = null;
        var chainStartedAt = Date.now();
        var CHAIN_DEADLINE_MS = 20000;   // R3.6 - hard cap, no matter how many models left
        // 404 on a deprecated model is NOT a real "stop the chain" signal -
        // the model just doesnt exist. Keep going. We only stop on auth (401/403),
        // quota (RESOURCE_EXHAUSTED with quota), or actual permission errors.
        for (var i = 0; i < chain.length; i++) {
            if (Date.now() - chainStartedAt > CHAIN_DEADLINE_MS) {
                gs.warn('[NetraGemini] chain deadline hit after ' + i + ' attempts - giving up');
                return { error: 'chain_deadline: ' + (lastErr || 'no model returned in 20s') };
            }
            var result = _callGeminiOnce(apiKey, chain[i], contents, tools, systemInstruction);
            if (!result.error) {
                if (i > 0) {
                    gs.info('[NetraGemini] fallback succeeded on ' + chain[i] + ' after ' + i + ' failures');
                    data.last_model_used = chain[i];
                }
                result._model_used = chain[i];
                return result;
            }
            lastErr = result.error;
            var transient = lastErr.indexOf('503') >= 0 ||
                            lastErr.indexOf('429') >= 0 ||
                            lastErr.indexOf('500') >= 0 ||
                            lastErr.indexOf('UNAVAILABLE') >= 0 ||
                            lastErr.indexOf('overloaded') >= 0 ||
                            lastErr.indexOf('high demand') >= 0 ||
                            // 404 "model not found" is treated as transient (skip and continue)
                            // because we always want to try the next model, not abort.
                            (lastErr.indexOf('404') >= 0 && lastErr.indexOf('not found') >= 0) ||
                            (lastErr.indexOf('404') >= 0 && lastErr.indexOf('is not supported') >= 0);
            if (!transient) {
                gs.warn('[NetraGemini] non-transient error on ' + chain[i] + ': ' + lastErr.substring(0, 200));
                return result;
            }
            // For 404 vs busy, log differently so debugging stays clear
            if (lastErr.indexOf('404') >= 0) {
                gs.info('[NetraGemini] ' + chain[i] + ' is retired/missing, trying next model');
            } else {
                gs.info('[NetraGemini] ' + chain[i] + ' is busy, falling through to next model');
            }
        }
        return { error: 'All fallback models exhausted. Last: ' + lastErr };
    }

    function _callGeminiOnce(apiKey, model, contents, tools, systemInstruction) {
        var url = 'https://generativelanguage.googleapis.com/v1beta/models/' +
                  encodeURIComponent(model) + ':generateContent?key=' + encodeURIComponent(apiKey);
        var body = {
            contents: contents,
            tools: tools,
            systemInstruction: systemInstruction,
            generationConfig: {
                temperature: 0.7,
                // R2.12.1 - bumped 512 -> 1024 AND disabled internal thinking.
                // Gemini 2.5 Flash with thinking enabled was eating the entire
                // 512-token budget on hidden reasoning tokens, leaving the
                // visible reply EMPTY ("I got an empty response"). Disabling
                // thinking + giving more output budget restores chat replies.
                // Release X: 1024 -> 2048 so long briefings never truncate.
                maxOutputTokens: 2048,
                topP: 0.95,
                thinkingConfig: { thinkingBudget: 0 }
            },
            // R2 - encourage Gemini to call multiple tools in ONE turn rather
            // than chain them across iterations - that halves latency for
            // multi-step commands like "list my tickets and my approvals".
            toolConfig: {
                functionCallingConfig: { mode: 'AUTO' }
            },
            // R1: relax default safety filters - this is an internal corporate
            // assistant. Corporate directory lookups, ticket text, and routine
            // language must not be blocked by overly-cautious filters.
            safetySettings: [
                { category: 'HARM_CATEGORY_HARASSMENT',        threshold: 'BLOCK_ONLY_HIGH' },
                { category: 'HARM_CATEGORY_HATE_SPEECH',       threshold: 'BLOCK_ONLY_HIGH' },
                { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_ONLY_HIGH' },
                { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_ONLY_HIGH' }
            ]
        };
        try {
            var rm = new sn_ws.RESTMessageV2();
            rm.setEndpoint(url);
            rm.setHttpMethod('POST');
            rm.setRequestHeader('Content-Type', 'application/json');
            rm.setRequestBody(JSON.stringify(body));
            // R2.12.5 - 30s -> 12s. Fail fast and fall back. The whole chain
            // worst-case is now 6 models x 12s = 72s, but typical hit on
            // flash-lite is 0.5-2s.
            rm.setHttpTimeout(12000);
            var r = rm.execute();
            var code = r.getStatusCode();
            var rb = r.getBody();
            if (code !== 200) {
                return { error: 'HTTP ' + code + ': ' + String(rb || '').substring(0, 400) };
            }
            return JSON.parse(rb);
        } catch (e) {
            return { error: 'Could not call Gemini: ' + String(e.message || e) };
        }
    }

    /* ===================================================================
     *  R2.11 - NETRA REASONING ENGINE
     *
     *  Replicates Anthropic-style structured reasoning (chain-of-thought,
     *  JSON output mode, self-verification) using ONLY the free Gemini
     *  API. No paid dependencies.
     *
     *  Three primitives:
     *  - _reason()      single-call reasoning with structured-output schema
     *  - _reasonText()  free-form narrative output
     *  - _verify()      optional second-pass self-critique on the first output
     *
     *  These wrap _callGemini with:
     *  - responseMimeType: 'application/json' + responseSchema for tools
     *    that need machine-parseable output (strict structured tool use)
     *  - "Think step by step" preamble for chain-of-thought
     *  - Higher maxOutputTokens (2048) for reasoning tasks vs 512 for chat
     *  - Verbose system text that forces explicit reasoning before answer
     * =================================================================== */
    function _reason(systemText, userPayload, responseSchema, maxOutputTokens) {
        var apiKey = gs.getProperty(SCOPE + '.gemini_api_key');
        if (!apiKey) return { error: 'no_gemini_key' };
        // R4.7 - PERF: reasoning calls (sentiment, triage) also default to the
        // fast lite model. These run on the request path, so 2.5-flash's
        // thinking overhead was pure added latency.
        var model = gs.getProperty(SCOPE + '.gemini_model', 'gemini-flash-lite-latest');

        // Wrap the system text with a chain-of-thought preamble. This is the
        // single most-effective prompting trick from Anthropic's playbook:
        // tell the model to think before answering, and the answer quality
        // jumps measurably even on smaller models.
        var coT = 'Think step by step. First, analyse the user payload carefully. ' +
                  'Identify the relevant entities, relationships, and constraints. ' +
                  'Then construct your answer.\n\n' + (systemText || '');

        var body = {
            contents: [{ role: 'user', parts: [{ text: String(userPayload) }] }],
            systemInstruction: { parts: [{ text: coT }] },
            generationConfig: {
                temperature: 0.3,                  // Lower temp for structured-output reliability
                maxOutputTokens: maxOutputTokens || 2048,
                topP: 0.9,
                // Disable Gemini 2.5 Flash thinking tokens — they otherwise
                // eat the maxOutputTokens budget and the visible reply gets
                // truncated mid-sentence. Our chain-of-thought scaffolding
                // is in the system prompt, so we don't need the model's
                // internal reasoning tokens too.
                thinkingConfig: { thinkingBudget: 0 }
            },
            safetySettings: [
                { category: 'HARM_CATEGORY_HARASSMENT',        threshold: 'BLOCK_ONLY_HIGH' },
                { category: 'HARM_CATEGORY_HATE_SPEECH',       threshold: 'BLOCK_ONLY_HIGH' },
                { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_ONLY_HIGH' },
                { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_ONLY_HIGH' }
            ]
        };
        // Structured output: when responseSchema is provided, Gemini guarantees
        // the output is a valid JSON object matching that schema. This is the
        // same idea as strict tool-input JSON schema enforcement.
        if (responseSchema) {
            body.generationConfig.responseMimeType = 'application/json';
            body.generationConfig.responseSchema   = responseSchema;
        }

        var url = 'https://generativelanguage.googleapis.com/v1beta/models/' +
                  encodeURIComponent(model) + ':generateContent?key=' + encodeURIComponent(apiKey);
        try {
            var rm = new sn_ws.RESTMessageV2();
            rm.setEndpoint(url);
            rm.setHttpMethod('POST');
            rm.setRequestHeader('Content-Type', 'application/json');
            rm.setRequestBody(JSON.stringify(body));
            // R2.12.5 - 45s -> 15s. Reasoning calls are slightly larger
            // than chat (more tokens) but still shouldn't sit forever.
            rm.setHttpTimeout(15000);
            var r = rm.execute();
            var code = r.getStatusCode();
            var rb = r.getBody();
            if (code !== 200) {
                return { error: 'HTTP ' + code + ': ' + String(rb || '').substring(0, 300) };
            }
            var parsed = JSON.parse(rb);
            var text = '';
            try {
                text = parsed.candidates[0].content.parts.map(function(p){ return p.text || ''; }).join('').trim();
            } catch (e) { return { error: 'no_candidate_text' }; }
            if (!text) return { error: 'empty_text' };
            if (responseSchema) {
                try { return { ok: true, json: JSON.parse(text), raw: text }; }
                catch (eP) { return { error: 'invalid_json', raw: text }; }
            }
            return { ok: true, text: text };
        } catch (e) {
            return { error: 'Reason call threw: ' + (e.message || e) };
        }
    }

    // Convenience wrapper for free-form narration tasks
    function _reasonText(systemText, userPayload, maxOutputTokens) {
        return _reason(systemText, userPayload, null, maxOutputTokens || 800);
    }

    /* ===================================================================
     *  System prompt - Indian English persona
     * =================================================================== */
    function _systemPrompt(liveMode) {
        // R8.2 - on the dedicated Live stage Netra never navigates away.
        var liveAddendum = !liveMode ? '' :
'\n' +
'LIVE STAGE MODE (you are on the dedicated /sp?id=netra_live page):\n' +
'- NEVER navigate away from this page, open records, click page buttons, or open URLs - those tools are disabled here. If the user asks to open something, DESCRIBE it fully by voice instead (summarize_ticket, describe_form, related_records) and mention they can open it in another tab while you keep talking here.\n';
        // R8 - writes are on by default; the addendum flips to a notice
        // only when the admin kill-switch has stripped the write tools.
        var writeAddendum = _ticketWritesEnabled() ?
'\n' +
'FIELD vs COMMENT: if the user names a SPECIFIC FIELD ("change the urgency of INC1234 to high"), call update_field, NOT update_ticket. update_ticket is ONLY for free-form customer-visible comments.\n'
        :
'\n' +
'TICKET WRITES ARE TEMPORARILY DISABLED (admin kill-switch). The create/modify tools are stripped from your toolset right now. If asked to create or change a ticket, say so in one graceful line and pivot to the read-only help you CAN give: status, summary, search, watchlist.\n';
        return {
            parts: [{
                text:
'You are Netra, a female voice assistant for ServiceNow, designed specifically for blind and visually-impaired users.\n' +
// R11 - dont literally call the admin "System" (PDI admin display name is
// "System Administrator") - fall back to a nameless warm address instead
(function () {
    var dn = gs.getUserDisplayName() || '';
    var fn = dn.split(' ')[0] || '';
    if (/^system$/i.test(fn) || !fn) {
        return 'You are speaking with the instance admin. Do NOT invent a name for them and never call them "System" - just speak warmly without a name. ';
    }
    return 'You are speaking with ' + dn + '. Call them by their first name "' + fn + '" naturally in conversation - not in every sentence, but at the start of replies and at transitions. ';
})() +
'PERSONALITY (R7 - witty companion): you are quick-witted, playful and a little cheeky - a sharp friend who happens to run ServiceNow. Light humor in SMALL doses: a wry aside, a playful jab at a P4 that has been open for 90 days, a dry "well, that\'s new" at a weird error. Humor NEVER delays the answer - the fact always lands first, the wit rides along. Never joke about security incidents, outages affecting people, or the user\'s mistakes. Be warm, be empathetic when it matters, and drop the comedy instantly if the user sounds stressed.\n' +
'\n' +
'CRITICAL - ACCESSIBILITY CONTEXT:\n' +
'- The user is BLIND. They cannot see anything on the screen.\n' +
'- Everything happens via voice. There is no chat panel, no buttons to click, no text to read.\n' +
'- Never reference visual elements ("click here", "see the screen", "look at the list", "as shown").\n' +
'- Confirm every action verbally and completely. Do not assume the user can verify on screen.\n' +
'- Speak the entire result, do not say things like "the list is shown above".\n' +
'\n' +
'VOICE & LANGUAGE STYLE - R7 (fluent, playful, with audible prosody):\n' +
'- You speak FLUENT, MODERN CONVERSATIONAL ENGLISH - the register of a great voice assistant, not a call centre. Tight phrasing, natural rhythm, personality in the word choice. (Your voice is an international multilingual neural voice; mirror the user\'s own language or Hinglish mix per the LANGUAGE MIRRORING rules.)\n' +
'- TIGHT IS BETTER THAN VERBOSE. Keep each reply to one or two short sentences. Long thoughts belong in follow-ups.\n' +
'- USE NATURAL VERBAL FILLERS LIKE A HUMAN: "umm,", "uhh,", "hmm,", "well,", "ah,", "right," sprinkled at the start of a sentence or before a transition. One or two per reply, where a real person would think. Bad (none): "You have eight tickets." Bad (too many): "Hmm, well, umm, you have, ah, eight tickets." Good: "Hmm, right, you have eight tickets."\n' +
'- WRAP IMPORTANT WORDS IN DOUBLE ASTERISKS so the TTS engine STRESSES them. Wrap: ticket numbers on first mention, priorities ("**P1**", "**critical**"), states ("**resolved**", "**in progress**"), key actions ("**escalating**", "**closed**"), counts ("**eight** incidents"), dates that matter ("**Friday**"). Example: "Mihir, **INC0008001** is **resolved**, marked **complete** five minutes ago." Aim for 2 to 4 stress words per non-trivial reply. SKIP STRESS only for pure greetings ("Hi Mihir") or one-line confirmations ("Done."). When the reply names a ticket, state, priority, count or date you MUST wrap at least one word.\n' +
'- USE ELLIPSIS "..." FOR THINKING PAUSES inside a sentence when you would naturally trail off or pick the next thought. Example: "Hmm, looks like... yes, eight open tickets." or "Right, well... the priority is **P1**." One ellipsis per reply at most.\n' +
'- USE EM-DASHES " - " for natural breaths in longer thoughts; full stops are perfect when a sentence is tight.\n' +
'- DROP ROBOTIC TEMPLATES. Never say "I have done X", "I will revert back", "kindly note". Say "Done", "Resolved", "On it", "Yep".\n' +
'- USE CONTRACTIONS: "you have" -> "you\'ve", "I will" -> "I\'ll", "do not" -> "don\'t", "it is" -> "it\'s".\n' +
'- Pronounce ticket numbers letter-by-digit ONLY when first mentioning them. After that just "it" or "that one".\n' +
'  First mention: "**I N C zero zero zero eight zero zero one** is resolved."  Follow-up: "Want me to add a comment to it?"\n' +
'- DO NOT GREET on every turn. Just answer. Greetings only at first contact and morning briefing.\n' +
'- DO NOT end with "anything else?" every time. Sometimes just stop. Vary: "What next?" / "Want me to escalate?" / nothing.\n' +
'- IDIOMS: casual and current. "Done", "Right", "On it", "Easy", "Say less" are fine. Never "kindly", never "do the needful", never "please be informed".\n' +
'- ALLOWED MARKDOWN: only **double-asterisk emphasis** and "..." for pauses. No headers, bullets, code blocks, or single asterisks for italics - those break the TTS.\n' +
'\n' +
'RELEASE X - HUMAN TURN-TAKING (the client now supports true barge-in):\n' +
'- The user can talk over you and your voice stops instantly, exactly like interrupting a colleague. When a message arrives after an interruption, it IS the new topic - answer it directly. No "as I was saying", no resuming the old answer unless they ask.\n' +
